/* ===== TREINO COM AULA: CIÊNCIAS ===== */
(function(){
const {tema, pick, rint, mix, sample, quatro, numW, N, fmtU, outras, fr, R} = TREINO;

/* linha de tabela → questão; erradas = respostas de outras linhas. pergunta(l) monta o enunciado */
function deTabela(linhas, pergunta, como, explica, iResp){
  iResp = iResp===undefined ? 1 : iResp;
  return function(){
    const l=pick(linhas), c=l[iResp];
    return {q:pergunta(l), como, c, w:outras(linhas,l,x=>x[iResp]).slice(0,4), e:explica(l)};
  };
}
/* questão de rótulo fixo: linha = [situação, rótulo, explicação] */
function rotulo(linhas, rotulos, pergunta, como, def){
  return function(){
    const l=pick(linhas), c=l[1];
    return {q:pergunta(l), como, c, w:quatro(c,mix(rotulos.filter(r=>r!==c))), e:(l[2]||"")+(def&&def[c]?" "+def[c]:""), def};
  };
}
const alterna = (...gs) => function(){ return pick(gs).call(this); };

/* ---------- 1. SUBSTÂNCIAS E MISTURAS ---------- */
const SUBS=[["água (H₂O)","composta","hidrogênio e oxigênio"],["gás oxigênio (O₂)","simples","só oxigênio"],["ozônio (O₃)","simples","só oxigênio"],["ferro (Fe)","simples","só ferro"],["grafite (C)","simples","só carbono"],["diamante (C)","simples","só carbono"],["gás carbônico (CO₂)","composta","carbono e oxigênio"],["sal de cozinha (NaCl)","composta","sódio e cloro"],["gás hidrogênio (H₂)","simples","só hidrogênio"],["amônia (NH₃)","composta","nitrogênio e hidrogênio"],["metano (CH₄)","composta","carbono e hidrogênio"],["gás nitrogênio (N₂)","simples","só nitrogênio"],["glicose (C₆H₁₂O₆)","composta","carbono, hidrogênio e oxigênio"],["ouro (Au)","simples","só ouro"]];
const MIST=[["água e sal dissolvido","homogênea","uma só fase: não dá para ver o sal"],["água e óleo","heterogênea","duas fases: o óleo fica por cima"],["ar filtrado","homogênea","os gases se misturam por completo"],["água e areia","heterogênea","a areia fica visível no fundo"],["álcool e água","homogênea","misturam-se totalmente"],["granito","heterogênea","dá para ver grãos de cores diferentes"],["café coado","homogênea","uma só fase"],["água e gelo","heterogênea","um só material, mas em duas fases (líquido e sólido)"],["leite (ao microscópio)","heterogênea","ao microscópio veem-se gotas de gordura"],["vinagre","homogênea","ácido acético dissolvido em água"],["salada de frutas","heterogênea","vemos cada pedaço"],["refrigerante com bolhas","heterogênea","o gás das bolhas forma outra fase"]];
tema({id:"c-substancias", s:2, nome:"Matéria: substâncias simples, compostas e misturas",
aula:`<p>Tudo é feito de <b>matéria</b>, e a matéria é formada por <b>átomos</b>. Cada tipo de átomo é um <b>elemento químico</b> (hidrogênio H, oxigênio O, carbono C...).</p>
<h4>Substância pura</h4><ul><li><b>Simples</b>: formada por <b>um só elemento</b>. O₂ (oxigênio), O₃ (ozônio), Fe (ferro), C (grafite, diamante).</li><li><b>Composta</b>: formada por <b>dois ou mais elementos diferentes</b>. H₂O (água: H e O), CO₂ (C e O), NaCl (Na e Cl).</li></ul>
<p><i>Truque: olhe a fórmula e conte os <b>tipos de letra maiúscula</b>. Uma só (O₂, O₃, Fe) → simples. Mais de uma (H₂O, CO₂) → composta. O número pequeno embaixo não importa para isso.</i></p>
<h4>Mistura</h4><p>Duas ou mais substâncias juntas, sem formar uma nova.</p><ul><li><b>Homogênea</b> (solução): <b>uma só fase</b>, parece uma coisa só. Água com sal dissolvido, ar, álcool com água.</li><li><b>Heterogênea</b>: <b>duas ou mais fases</b> visíveis. Água e óleo, água e areia, granito.</li></ul>
<p><b>Fase</b> = cada parte com aspecto diferente que dá para distinguir. Água + óleo + areia = 3 fases. Atenção: água com gelo é uma substância só, mas tem 2 fases.</p>
<h4>Alotropia</h4><p>Um mesmo elemento formando substâncias simples diferentes: oxigênio (O₂) e ozônio (O₃); grafite e diamante (ambos carbono).</p>`,
gen: alterna(
  rotulo(SUBS,["simples","composta","mistura homogênea","mistura heterogênea","elemento químico isolado"],l=>"A substância "+l[0]+" é classificada como:","Olhe a fórmula e conte quantos ELEMENTOS diferentes aparecem (letras maiúsculas diferentes). Um só → simples. Dois ou mais → composta. Substância pura não é mistura.",{simples:"Simples: um único elemento.",composta:"Composta: dois ou mais elementos diferentes.","mistura homogênea":"Mistura tem mais de uma substância; aqui há uma só.","mistura heterogênea":"Mistura tem mais de uma substância; aqui há uma só.","elemento químico isolado":"Elemento é o tipo de átomo; a substância é formada por átomos ligados."}),
  function(){ const l=pick(SUBS); return {q:"A substância "+l[0]+" é formada por:",como:"Leia as letras maiúsculas da fórmula: cada uma é um elemento (H = hidrogênio, O = oxigênio, C = carbono, N = nitrogênio, Na = sódio, Cl = cloro).",c:l[2],w:outras(SUBS,l,x=>x[2]).slice(0,4),e:l[0]+": "+l[2]+", por isso é "+l[1]+"."}; },
  rotulo(MIST,["homogênea","heterogênea"].concat(["substância simples","substância composta","não é mistura"]),l=>"A mistura de "+l[0]+" é:","Olhe (ou imagine) a mistura: dá para ver mais de uma parte (fase)? Então é heterogênea. Parece uma coisa só, sem separação visível? Homogênea.",{homogênea:"Homogênea: uma só fase.",heterogênea:"Heterogênea: duas ou mais fases.","substância simples":"Há mais de uma substância: é mistura.","substância composta":"Há mais de uma substância misturada, sem reação: é mistura.","não é mistura":"Há mais de uma substância juntas: é mistura."})
)});

/* ---------- 2. ESTADOS FÍSICOS ---------- */
const MUD=[["sólido","líquido","fusão"],["líquido","sólido","solidificação"],["líquido","gasoso","vaporização"],["gasoso","líquido","condensação (liquefação)"],["sólido","gasoso","sublimação"],["gasoso","sólido","sublimação inversa (ressublimação)"]];
const EX_MUD=[["O gelo derrete fora da geladeira.","fusão"],["A água vira gelo no congelador.","solidificação"],["A roupa seca no varal.","vaporização"],["A água ferve na panela.","vaporização"],["Gotas aparecem do lado de fora de um copo gelado.","condensação (liquefação)"],["O espelho do banheiro embaça no banho quente.","condensação (liquefação)"],["A naftalina diminui de tamanho no armário.","sublimação"],["O gelo-seco solta “fumaça” sem derreter.","sublimação"],["A vela derrete perto da chama.","fusão"],["A lava do vulcão esfria e vira rocha.","solidificação"],["A geada se forma direto do vapor do ar em noites muito frias.","sublimação inversa (ressublimação)"]];
const MUDN=MUD.map(m=>m[2]);
tema({id:"c-estados", s:2, nome:"Estados físicos e mudanças de estado",
aula:`<p>A matéria aparece em três estados principais, conforme a <b>agitação e a distância</b> entre suas partículas:</p>
<table><tr><th>Estado</th><th>Forma</th><th>Volume</th><th>Partículas</th></tr><tr><td><b>Sólido</b></td><td>fixa</td><td>fixo</td><td>bem juntas, só vibram</td></tr><tr><td><b>Líquido</b></td><td>do recipiente</td><td>fixo</td><td>próximas, deslizam</td></tr><tr><td><b>Gasoso</b></td><td>do recipiente</td><td>variável</td><td>muito afastadas e agitadas</td></tr></table>
<h4>Mudanças de estado</h4><table><tr><th>De → Para</th><th>Nome</th><th>Exemplo</th></tr>
<tr><td>sólido → líquido</td><td><b>Fusão</b></td><td>gelo derretendo</td></tr><tr><td>líquido → sólido</td><td><b>Solidificação</b></td><td>água virando gelo</td></tr><tr><td>líquido → gasoso</td><td><b>Vaporização</b> (evaporação lenta, ebulição = fervura, calefação = gota na chapa quente)</td><td>roupa secando, água fervendo</td></tr><tr><td>gasoso → líquido</td><td><b>Condensação</b> (liquefação)</td><td>copo gelado “suando”, espelho embaçado</td></tr><tr><td>sólido → gasoso</td><td><b>Sublimação</b></td><td>naftalina, gelo-seco</td></tr><tr><td>gasoso → sólido</td><td><b>Sublimação inversa</b></td><td>geada</td></tr></table>
<p><b>Ganhando calor</b>: fusão, vaporização, sublimação (as partículas se agitam mais). <b>Perdendo calor</b>: solidificação, condensação.</p>
<p>A água pura funde a <b>0 °C</b> e ferve a <b>100 °C</b> (ao nível do mar). Durante a mudança de estado de uma substância pura, a temperatura <b>fica constante</b>.</p>`,
gen: alterna(
  function(){ const m=pick(MUD); return {q:"A passagem do estado "+m[0]+" para o estado "+m[1]+" chama-se:",como:"Lembre da tabela: sólido→líquido fusão; líquido→sólido solidificação; líquido→gás vaporização; gás→líquido condensação; sólido→gás sublimação.",c:m[2],w:quatro(m[2],mix(MUDN)),e:m[0]+" → "+m[1]+" = "+m[2]+"."}; },
  function(){ const [f,c]=pick(EX_MUD); return {q:"“"+f+"” Esse fenômeno é um exemplo de:",como:"Descubra o estado inicial e o final do material (ex.: gelo sólido → água líquida). Depois dê o nome da passagem. Gotas que aparecem do nada vêm do vapor do ar (condensação).",c,w:quatro(c,mix(MUDN)),e:"É "+c+"."}; }
)});

/* ---------- 3. SEPARAÇÃO DE MISTURAS ---------- */
const SEP=[["água e areia","decantação ou filtração","a areia, sólida e mais densa, fica no fundo ou presa no filtro"],["água e sal dissolvido (recuperando a água)","destilação simples","a água evapora, é resfriada e recolhida; o sal fica"],["sal da água do mar nas salinas","evaporação","o sol evapora a água e o sal fica"],["água e óleo","funil de decantação","os líquidos não se misturam; o mais denso sai por baixo"],["limalha de ferro e areia","separação magnética","o ímã atrai só o ferro"],["feijão e pedrinhas","catação","separa-se com as mãos"],["arroz e casca (com vento)","ventilação","o vento leva a casca, mais leve"],["areia fina e pedras","peneiração","os grãos pequenos passam pela peneira"],["café em pó e água quente","filtração","o filtro segura o pó e deixa passar o líquido"],["petróleo (gasolina, diesel...)","destilação fracionada","cada líquido ferve a uma temperatura diferente"],["sangue (plasma e células)","centrifugação","a rotação rápida joga o mais denso para o fundo"],["água e álcool","destilação fracionada","os líquidos misturados têm pontos de ebulição diferentes"]];
tema({id:"c-separacao", s:2, nome:"Separação de misturas",
aula:`<p>O método depende do <b>tipo de mistura</b> e da diferença entre os componentes (tamanho, densidade, ponto de ebulição, magnetismo).</p>
<h4>Misturas heterogêneas</h4><ul><li><b>Catação</b>: com as mãos (feijão e pedrinhas).</li><li><b>Peneiração</b>: grãos de tamanhos diferentes (areia e pedras).</li><li><b>Ventilação</b>: o vento leva o mais leve (casca do arroz).</li><li><b>Separação magnética</b>: o ímã atrai o ferro.</li><li><b>Decantação</b>: deixar parado; o mais denso desce (água e areia). Para dois líquidos que não se misturam (água e óleo), usa-se o <b>funil de decantação</b>.</li><li><b>Filtração</b>: o filtro retém o sólido (café, água e areia).</li><li><b>Centrifugação</b>: girar muito rápido para acelerar a decantação (sangue, leite).</li></ul>
<h4>Misturas homogêneas</h4><ul><li><b>Evaporação</b>: perde-se o líquido, fica o sólido (salinas).</li><li><b>Destilação simples</b>: sólido dissolvido em líquido, <b>recuperando o líquido</b> (água e sal): aquece, o vapor vai pelo condensador e vira líquido de novo.</li><li><b>Destilação fracionada</b>: <b>líquidos misturados</b> com pontos de ebulição diferentes (água e álcool, petróleo).</li></ul>
<p><b>Pegadinha:</b> filtração <b>não</b> separa sal dissolvido da água: o sal passa pelo filtro.</p>`,
gen: deTabela(SEP,l=>"Qual o método mais adequado para separar "+l[0]+"?","Primeiro diga se a mistura é homogênea (uma fase) ou heterogênea (fases visíveis). Depois pense na diferença entre os componentes: tamanho (peneira), densidade (decantação), um é atraído por ímã (magnética), pontos de ebulição (destilação).",l=>"Método: "+l[1]+", porque "+l[2]+".")});

/* ---------- 4. ÁTOMO E TABELA PERIÓDICA ---------- */
const ELEM=[["H","hidrogênio",1,1],["He","hélio",2,4],["C","carbono",6,12],["N","nitrogênio",7,14],["O","oxigênio",8,16],["Na","sódio",11,23],["Mg","magnésio",12,24],["Al","alumínio",13,27],["Cl","cloro",17,35],["K","potássio",19,39],["Ca","cálcio",20,40],["Fe","ferro",26,56],["Zn","zinco",30,65],["S","enxofre",16,32],["P","fósforo",15,31]];
const FAM=[["sódio (Na)","metal"],["ferro (Fe)","metal"],["cálcio (Ca)","metal"],["cobre (Cu)","metal"],["alumínio (Al)","metal"],["oxigênio (O)","ametal"],["cloro (Cl)","ametal"],["carbono (C)","ametal"],["nitrogênio (N)","ametal"],["enxofre (S)","ametal"],["hélio (He)","gás nobre"],["neônio (Ne)","gás nobre"],["argônio (Ar)","gás nobre"],["hidrogênio (H)","hidrogênio (não se encaixa em nenhum grupo)"]];
tema({id:"c-atomo", s:2, nome:"Átomo e tabela periódica",
aula:`<p>O <b>átomo</b> é a menor parte de um elemento. Ele tem:</p><ul><li><b>Núcleo</b> (centro): <b>prótons</b> (carga +) e <b>nêutrons</b> (sem carga).</li><li><b>Eletrosfera</b> (em volta): <b>elétrons</b> (carga −), bem mais leves.</li></ul>
<h4>Os números do átomo</h4><ul><li><b>Z = número atômico = número de prótons</b>. É a “identidade” do elemento: todo átomo com 6 prótons é carbono.</li><li><b>A = número de massa = prótons + nêutrons</b>.</li><li>Logo, <b>nêutrons = A − Z</b>.</li><li>Átomo <b>neutro</b>: elétrons = prótons.</li></ul>
<p>Exemplo: sódio ₁₁Na²³ → Z = 11, A = 23 → 11 prótons, 11 elétrons, 23 − 11 = <b>12 nêutrons</b>.</p>
<h4>Íons</h4><p>Átomo que <b>ganhou ou perdeu elétrons</b>. Perdeu → fica positivo (cátion): Na⁺ tem 10 elétrons. Ganhou → negativo (ânion): Cl⁻ tem 18.</p><p><i>Truque: o sinal + quer dizer que “faltam” elétrons.</i></p>
<h4>Tabela periódica</h4><p>Organiza os elementos em ordem crescente de Z. <b>Linhas</b> = períodos; <b>colunas</b> = famílias (grupos), com propriedades parecidas.</p><ul><li><b>Metais</b> (maioria, à esquerda): brilham, conduzem calor e eletricidade, tendem a <b>perder</b> elétrons. Na, Fe, Cu, Al, Ca.</li><li><b>Ametais</b> (à direita): tendem a <b>ganhar</b> elétrons. O, N, C, Cl, S.</li><li><b>Gases nobres</b> (última coluna): quase não reagem. He, Ne, Ar.</li><li><b>Hidrogênio</b>: caso especial, fica no topo à esquerda, mas não é metal.</li></ul>`,
gen(){
  const t=R(4);
  if(t===3){ const l=pick(FAM); return {q:"Na tabela periódica, o elemento "+l[0]+" é classificado como:",como:"Metais ficam à esquerda e no centro (brilham, conduzem eletricidade). Ametais à direita. Gases nobres na última coluna. O hidrogênio é um caso à parte.",c:l[1],w:quatro(l[1],["metal","ametal","gás nobre","hidrogênio (não se encaixa em nenhum grupo)","semimetal"]),e:l[0]+" é "+l[1]+"."}; }
  const [s,nome,Z,A]=pick(ELEM), n=A-Z;
  if(t===0) return {q:"O átomo de "+nome+" tem número atômico Z = "+Z+" e número de massa A = "+A+". Quantos nêutrons ele tem?",como:"Massa = prótons + nêutrons. Os prótons são o número atômico (Z). Então nêutrons = A − Z = "+A+" − "+Z+".",c:N(n),w:numW(n,[A+Z,Z,A,n+1]),e:"Nêutrons = "+A+" − "+Z+" = "+n+"."};
  if(t===1) return {q:"Um átomo NEUTRO de "+nome+" ("+s+") tem número atômico "+Z+". Quantos elétrons ele possui?",como:"Número atômico Z = número de prótons. Átomo neutro tem cargas equilibradas: elétrons = prótons.",c:N(Z),w:numW(Z,[A,A-Z,Z+1,Z*2]),e:"Neutro: elétrons = prótons = Z = "+Z+"."};
  const carga=pick([1,2,-1,-2]), e=Z-carga; if(e<=0) return this.gen();
  const simb=s+(Math.abs(carga)===1?"":Math.abs(carga))+(carga>0?"⁺":"⁻");
  return {q:"Quantos elétrons tem o íon "+simb+" (Z = "+Z+")?",como:"Comece com Z = "+Z+" elétrons (átomo neutro). Carga positiva = PERDEU elétrons (subtraia). Carga negativa = GANHOU (some).",c:N(e),w:numW(e,[Z+carga,Z,A-Z,Z+2*carga]),e:simb+": "+(carga>0?"perdeu ":"ganhou ")+Math.abs(carga)+" → "+Z+(carga>0?" − ":" + ")+Math.abs(carga)+" = "+e+" elétrons."};
}});

/* ---------- 5. LIGAÇÕES QUÍMICAS ---------- */
const LIG=[["cloreto de sódio (NaCl)","iônica","Na é metal e Cl é ametal"],["óxido de magnésio (MgO)","iônica","Mg metal + O ametal"],["cloreto de cálcio (CaCl₂)","iônica","Ca metal + Cl ametal"],["brometo de potássio (KBr)","iônica","K metal + Br ametal"],["água (H₂O)","covalente (molecular)","H e O são ametais (o H se comporta como ametal)"],["gás carbônico (CO₂)","covalente (molecular)","C e O são ametais"],["metano (CH₄)","covalente (molecular)","C e H"],["gás oxigênio (O₂)","covalente (molecular)","O com O, dois ametais"],["amônia (NH₃)","covalente (molecular)","N e H"],["fio de cobre (Cu)","metálica","só átomos de metal"],["barra de ferro (Fe)","metálica","só metal"],["latão (cobre + zinco)","metálica","liga de metais"]];
const DEF_LIG={"iônica":"Iônica: metal + ametal; o metal PERDE elétrons e o ametal GANHA (formam íons que se atraem).","covalente (molecular)":"Covalente: ametal + ametal (ou H); os átomos COMPARTILHAM pares de elétrons.","metálica":"Metálica: metal + metal; “mar” de elétrons livres, que explica a condução de eletricidade."};
tema({id:"c-ligacoes", s:2, nome:"Ligações químicas",
aula:`<p>Átomos se ligam para ficar mais <b>estáveis</b>. A <b>regra do octeto</b> diz que muitos átomos ficam estáveis com <b>8 elétrons na última camada</b> (como os gases nobres).</p>
<table><tr><th>Ligação</th><th>Entre</th><th>O que acontece</th><th>Exemplos</th></tr>
<tr><td><b>Iônica</b></td><td>metal + ametal</td><td>O metal <b>doa</b> elétrons, o ametal <b>recebe</b>. Formam íons + e − que se atraem.</td><td>NaCl, MgO, CaCl₂</td></tr>
<tr><td><b>Covalente</b> (molecular)</td><td>ametal + ametal (ou H)</td><td>Os átomos <b>compartilham</b> elétrons.</td><td>H₂O, CO₂, O₂, CH₄</td></tr>
<tr><td><b>Metálica</b></td><td>metal + metal</td><td>Elétrons livres circulam entre os átomos (“mar de elétrons”).</td><td>Cu, Fe, ligas (bronze, aço)</td></tr></table>
<h4>Como decidir</h4><ol><li>Leia os elementos da fórmula.</li><li>Classifique cada um (metal, ametal, H).</li><li>Metal com ametal → iônica. Só ametais/H → covalente. Só metais → metálica.</li></ol>
<p><b>Consequências:</b> compostos iônicos formam cristais e conduzem eletricidade quando dissolvidos ou derretidos (água salgada conduz). Metais conduzem sempre, por causa dos elétrons livres.</p>`,
gen: rotulo(LIG,Object.keys(DEF_LIG).concat(["não há ligação, é mistura","nuclear"]),l=>"Que tipo de ligação química há em "+l[0]+"?","Classifique cada elemento: metais (Na, K, Mg, Ca, Fe, Cu, Al, Zn) e ametais (H, C, N, O, Cl, Br, S). Metal + ametal = iônica; ametal + ametal = covalente; metal + metal = metálica.",Object.assign({"não há ligação, é mistura":"Os átomos estão ligados quimicamente: é uma substância, não mistura.","nuclear":"Não existe “ligação nuclear” entre átomos em compostos comuns."},DEF_LIG))});

/* ---------- 6. ÁCIDOS, BASES E pH ---------- */
const PH=[["suco de limão",2,"ácido"],["vinagre",3,"ácido"],["refrigerante",3,"ácido"],["suco gástrico (estômago)",1,"ácido"],["café",5,"ácido"],["água pura",7,"neutro"],["sangue",7.4,"básico (alcalino)"],["leite de magnésia",10,"básico (alcalino)"],["sabão",10,"básico (alcalino)"],["água sanitária",12,"básico (alcalino)"],["soda cáustica",14,"básico (alcalino)"],["bicarbonato de sódio em água",8.5,"básico (alcalino)"],["tomate",4,"ácido"]];
tema({id:"c-ph", s:2, nome:"Ácidos, bases e pH",
aula:`<p>O <b>pH</b> é uma escala de <b>0 a 14</b> que mede se algo é ácido ou básico.</p>
<table><tr><th>pH</th><th>Meio</th><th>Exemplos</th></tr><tr><td>menor que 7</td><td><b>Ácido</b></td><td>limão (2), vinagre (3), refrigerante, suco gástrico (1)</td></tr><tr><td>igual a 7</td><td><b>Neutro</b></td><td>água pura</td></tr><tr><td>maior que 7</td><td><b>Básico</b> (alcalino)</td><td>sabão, leite de magnésia, água sanitária, soda cáustica</td></tr></table>
<p>Quanto <b>mais longe de 7</b>, mais forte: pH 1 é muito mais ácido que pH 5.</p>
<h4>Características</h4><ul><li><b>Ácidos</b>: sabor azedo, liberam H⁺ na água, corroem metais. Ex.: ácido clorídrico (HCl) no estômago.</li><li><b>Bases</b>: sabor adstringente (“amarra” a boca), sensação escorregadia, liberam OH⁻. Ex.: hidróxido de sódio (NaOH), soda cáustica.</li></ul>
<h4>Neutralização</h4><p><b>Ácido + base → sal + água.</b> Por isso o leite de magnésia (base) alivia a azia (excesso de ácido no estômago), e o pH vai para perto de 7.</p>
<h4>Indicadores</h4><p>Mudam de cor conforme o pH: <b>fenolftaleína</b> fica <b>rosa em base</b> e incolor em ácido; o suco de <b>repolho roxo</b> fica vermelho no ácido e verde/amarelo na base; o <b>papel tornassol</b> azul fica vermelho no ácido.</p>`,
gen: alterna(
  function(){ const [s,p,c]=pick(PH), rel=p<7?"menor que 7":p===7?"igual a 7":"maior que 7", cc=c+", pois o pH é "+rel;
    const ops=["ácido, pois o pH é maior que 7","básico (alcalino), pois o pH é menor que 7","neutro, pois o pH é maior que 7","ácido, pois o pH é menor que 7","básico (alcalino), pois o pH é maior que 7","neutro, pois o pH é igual a 7"];
    return {q:"O "+s+" tem pH aproximadamente "+N(p)+". Ele é:",como:"Compare com 7: menor que 7 = ácido; igual a 7 = neutro; maior que 7 = básico (alcalino).",c:cc,w:quatro(cc,mix(ops)),e:"pH "+N(p)+(p<7?" < 7 → ácido.":p===7?" = 7 → neutro.":" > 7 → básico.")}; },
  function(){ const [ps,ms]=[sample(PH,5),null]; const tipo=pick(["mais ácido","mais básico"]); const alvo=ps.reduce((m,x)=>(tipo==="mais ácido"?x[1]<m[1]:x[1]>m[1])?x:m); if(ps.some(x=>x!==alvo&&x[1]===alvo[1])) return this.gen();
    return {q:"Qual destas substâncias é a "+tipo.toUpperCase()+"? "+ps.map(x=>x[0]+" (pH "+N(x[1])+")").join("; ")+".",como:tipo==="mais ácido"?"Mais ácido = pH MENOR (mais perto de 0).":"Mais básico = pH MAIOR (mais perto de 14).",c:alvo[0],w:ps.filter(x=>x!==alvo).map(x=>x[0]),e:alvo[0]+" tem o pH "+(tipo==="mais ácido"?"menor":"maior")+": "+N(alvo[1])+"."}; },
  function(){ const q=pick([["Para aliviar a azia (excesso de ácido no estômago), toma-se leite de magnésia. Isso funciona porque ocorre uma:","neutralização: a base reage com o ácido"],["Uma gota de fenolftaleína deixou a solução rosa. A solução é:","básica (alcalina)"],["A reação entre um ácido e uma base produz:","sal e água"]]);
    const pool=["neutralização: a base reage com o ácido","básica (alcalina)","sal e água","ácida","neutra, com pH 0","gás oxigênio e água","fusão do ácido","oxidação do metal"];
    return {q:q[0],como:"Lembre: ácido + base → sal + água (neutralização). Fenolftaleína fica rosa só em meio básico.",c:q[1],w:quatro(q[1],mix(pool)),e:"Resposta: "+q[1]+"."}; }
)});

/* ---------- 7. REAÇÕES QUÍMICAS ---------- */
const FEN=[["Um prego enferruja na chuva.","químico","forma-se uma substância nova (ferrugem)"],["O papel queima.","químico","forma cinzas, gás e fumaça: novas substâncias"],["O bolo cresce e assa no forno.","químico","as substâncias da massa se transformam"],["Um comprimido efervescente solta bolhas na água.","químico","há liberação de gás novo"],["A banana amadurece e escurece.","químico","novas substâncias são formadas"],["O leite azeda.","químico","forma substâncias novas"],["O gelo derrete.","físico","continua sendo água, só muda de estado"],["Um vidro se quebra.","físico","continua sendo vidro"],["O açúcar se dissolve no café.","físico","o açúcar continua lá, só dissolvido"],["Amassar uma lata.","físico","muda só a forma"],["A água ferve.","físico","só mudança de estado"],["Cortar um papel em pedaços.","físico","continua sendo papel"]];
tema({id:"c-reacoes", s:2, nome:"Reações químicas e fenômenos",
aula:`<h4>Fenômeno físico × químico</h4><ul><li><b>Físico</b>: a substância <b>continua a mesma</b>; muda forma, tamanho ou estado. Derreter gelo, quebrar vidro, dissolver açúcar.</li><li><b>Químico</b> (reação química): <b>formam-se substâncias novas</b>. Queimar papel, ferro enferrujar, cozinhar um ovo, leite azedar.</li></ul>
<h4>Sinais de que houve reação</h4><p>Mudança de <b>cor</b>, liberação de <b>gás</b> (bolhas), formação de <b>sólido</b> (precipitado), liberação ou absorção de <b>calor/luz</b>, mudança de <b>cheiro</b>.</p>
<h4>Escrevendo uma reação</h4><p><b>Reagentes → Produtos</b>. Ex.: carvão + oxigênio → gás carbônico (C + O₂ → CO₂).</p>
<h4>Lei de Lavoisier (conservação da massa)</h4><p>“Na natureza nada se cria, nada se perde, tudo se transforma.” Num sistema fechado, <b>massa dos reagentes = massa dos produtos</b>. Se 12 g de carbono reagem com 32 g de oxigênio, formam 12 + 32 = <b>44 g</b> de gás carbônico.</p>
<p><b>Combustão</b> precisa de três coisas (triângulo do fogo): combustível, comburente (oxigênio) e calor. Tire uma e o fogo apaga.</p>`,
gen: alterna(
  rotulo(FEN,["químico","físico"].concat(["nuclear","biológico, não químico","não é fenômeno"]),l=>"“"+l[0]+"” é um fenômeno:","Pergunte: no final, ainda é a mesma substância? Se sim (só mudou forma ou estado), é físico. Se surgiu algo novo (cor, gás, cheiro, ferrugem, cinzas), é químico.",{"químico":"Químico: forma substância nova.","físico":"Físico: a substância continua a mesma.","nuclear":"Nuclear envolve o núcleo dos átomos (usinas, radiação), não é o caso.","biológico, não químico":"Processos dos seres vivos também são reações químicas.","não é fenômeno":"Toda transformação é um fenômeno."}),
  function(){ const a=rint(2,40), b=rint(2,40), p1=pick([0,rint(1,a+b-1)]), cc=a+b; const nomes=pick([["carbono","oxigênio","gás carbônico"],["ferro","enxofre","sulfeto de ferro"],["hidrogênio","oxigênio","água"],["magnésio","oxigênio","óxido de magnésio"]]);
    return {q:"Em um frasco fechado, "+a+" g de "+nomes[0]+" reagem completamente com "+b+" g de "+nomes[1]+", formando "+nomes[2]+". Qual a massa de "+nomes[2]+" formada?",como:"Lei de Lavoisier: em sistema fechado, a massa dos reagentes é igual à dos produtos. Some as massas que reagiram.",c:fmtU(cc,"g"),w:numW(cc,[Math.abs(a-b),a*b,a,b,cc/2].filter(x=>x>0),"g"),e:a+" g + "+b+" g = "+cc+" g (nada se perde)."}; }
)});

/* ---------- 8. ENERGIA ---------- */
const ENER=[["usina hidrelétrica","potencial gravitacional → cinética → elétrica"],["lanterna a pilha","química → elétrica → luminosa"],["ventilador","elétrica → cinética (movimento)"],["chuveiro elétrico","elétrica → térmica (calor)"],["painel solar","luminosa (solar) → elétrica"],["fotossíntese das plantas","luminosa → química"],["pessoa correndo após comer","química → cinética"],["usina eólica","cinética do vento → elétrica"],["fogão a gás","química → térmica"],["liquidificador","elétrica → cinética"],["lâmpada acesa","elétrica → luminosa (e térmica)"],["dínamo de bicicleta","cinética → elétrica"],["arco e flecha (ao soltar)","potencial elástica → cinética"]];
tema({id:"c-energia", s:2, nome:"Energia e suas transformações",
aula:`<p><b>Energia</b> é a capacidade de realizar trabalho, de provocar mudanças. Ela <b>não se cria nem se destrói</b>: só se <b>transforma</b> de uma forma em outra (princípio da conservação da energia).</p>
<table><tr><th>Forma</th><th>O que é</th></tr><tr><td><b>Cinética</b></td><td>do movimento (carro andando, vento)</td></tr><tr><td><b>Potencial gravitacional</b></td><td>guardada pela altura (água na represa)</td></tr><tr><td><b>Potencial elástica</b></td><td>guardada em mola ou elástico esticado</td></tr><tr><td><b>Química</b></td><td>guardada nas substâncias (alimento, pilha, gás, gasolina)</td></tr><tr><td><b>Elétrica</b></td><td>da corrente elétrica</td></tr><tr><td><b>Térmica</b></td><td>calor</td></tr><tr><td><b>Luminosa</b></td><td>luz</td></tr><tr><td><b>Sonora</b></td><td>som</td></tr><tr><td><b>Nuclear</b></td><td>do núcleo do átomo</td></tr></table>
<h4>Como pensar</h4><p>Pergunte: <b>de onde vem</b> a energia que o aparelho usa? E <b>no que ela vira</b>? Ventilador: recebe elétrica, produz movimento → elétrica → cinética.</p>
<h4>Fontes</h4><p><b>Renováveis</b> (não acabam): solar, eólica, hidrelétrica, biomassa. <b>Não renováveis</b>: petróleo, carvão, gás natural (combustíveis fósseis), nuclear.</p>`,
gen: alterna(
  deTabela(ENER,l=>"Qual é a principal transformação de energia em: "+l[0]+"?","Identifique a energia que entra (o que “alimenta”: tomada = elétrica; pilha/alimento/gás = química; altura = potencial; sol = luminosa) e a que sai (movimento = cinética; calor = térmica; luz = luminosa).",l=>l[0]+": "+l[1]+"."),
  function(){ const r=pick([["solar","renovável"],["eólica","renovável"],["hidrelétrica","renovável"],["biomassa (bagaço de cana)","renovável"],["petróleo","não renovável"],["carvão mineral","não renovável"],["gás natural","não renovável"],["nuclear (urânio)","não renovável"]]);
    return {q:"A fonte de energia "+r[0]+" é:",como:"Renovável = a natureza repõe rápido (sol, vento, água dos rios, plantas). Não renovável = existe em quantidade limitada e leva milhões de anos para se formar (petróleo, carvão, gás, urânio).",c:r[1],w:["renovável","não renovável","inesgotável e poluente","nuclear","química"].filter(x=>x!==r[1]).slice(0,4),e:r[0]+": "+r[1]+"."}; }
)});

/* ---------- 9. TEMPERATURA E ESCALAS ---------- */
tema({id:"c-temperatura", s:2, nome:"Temperatura e escalas (°C, K, °F)",
aula:`<p><b>Temperatura</b> mede o grau de <b>agitação das partículas</b> de um corpo. <b>Calor</b> é a energia que passa do corpo mais quente para o mais frio. (Não são a mesma coisa!)</p>
<table><tr><th>Escala</th><th>Gelo derretendo</th><th>Água fervendo</th></tr><tr><td>Celsius (°C)</td><td>0</td><td>100</td></tr><tr><td>Kelvin (K)</td><td>273</td><td>373</td></tr><tr><td>Fahrenheit (°F)</td><td>32</td><td>212</td></tr></table>
<h4>Conversões</h4><ul><li><b>K = °C + 273</b> e <b>°C = K − 273</b>. Ex.: 27 °C = 300 K.</li><li><b>°F = 1,8 × °C + 32</b>. Ex.: 20 °C = 1,8 × 20 + 32 = 68 °F.</li><li><b>°C = (°F − 32) ÷ 1,8</b>. Ex.: 50 °F = 18 ÷ 1,8 = 10 °C.</li></ul>
<p><b>Kelvin</b> é a escala absoluta: começa no <b>zero absoluto</b> (0 K = −273 °C), a menor temperatura possível. Não usa o símbolo de grau: escreve-se “300 K”.</p>
<p><b>Equilíbrio térmico</b>: dois corpos em contato trocam calor até ficarem com a mesma temperatura.</p>`,
gen(){
  const t=R(4);
  if(t===0){ const c=rint(-40,150); return {q:"Uma temperatura de "+N(c)+" °C corresponde a quantos kelvin?",como:"K = °C + 273. Some 273 a "+N(c)+".",c:fmtU(c+273,"K"),w:numW(c+273,[c-273,273-c,c+100,c],"K",true),e:N(c)+" + 273 = "+(c+273)+" K."}; }
  if(t===1){ const k=rint(200,450); return {q:"Uma temperatura de "+k+" K corresponde a quantos graus Celsius?",como:"°C = K − 273. Subtraia 273 de "+k+".",c:fmtU(k-273,"°C"),w:numW(k-273,[k+273,273-k,k-100],"°C",true),e:k+" − 273 = "+N(k-273)+" °C."}; }
  if(t===2){ const c=rint(-2,10)*5*(R(2)?1:2), f=1.8*c+32; return {q:"Quanto é "+N(c)+" °C em graus Fahrenheit? (°F = 1,8 × °C + 32)",como:"Multiplique "+N(c)+" por 1,8 e depois some 32 (nesta ordem).",c:fmtU(f,"°F"),w:numW(f,[1.8*(c+32),c+32,1.8*c,c*2+32].filter(x=>x!==f),"°F",true),e:"1,8 × "+N(c)+" = "+N(1.8*c)+"; + 32 = "+N(f)+" °F."}; }
  const c=rint(-2,10)*5*2, f=1.8*c+32; return {q:"Um termômetro americano marca "+N(f)+" °F. Quanto é em °C? (°C = (°F − 32) ÷ 1,8)",como:"Primeiro subtraia 32 de "+N(f)+"; depois divida o resultado por 1,8.",c:fmtU(c,"°C"),w:numW(c,[f-32,(f+32)/1.8,f/1.8,c+32].filter(x=>Math.abs(x-c)>0.01),"°C",true),e:N(f)+" − 32 = "+N(f-32)+"; ÷ 1,8 = "+N(c)+" °C."};
}});

/* ---------- 10. PROPAGAÇÃO DO CALOR ---------- */
const CAL=[["A colher de metal esquenta inteira dentro da panela quente.","condução","o calor passa de partícula em partícula no sólido"],["O cabo da panela fica quente.","condução","contato direto, dentro do sólido"],["A mão esquenta ao segurar uma xícara de chá quente.","condução","contato direto"],["A água da panela esquenta por inteiro, mesmo aquecida só embaixo.","convecção","a água quente sobe e a fria desce (correntes)"],["O ar-condicionado é instalado no alto da parede.","convecção","o ar frio, mais denso, desce"],["O congelador fica na parte de cima da geladeira.","convecção","o ar frio desce e circula"],["A brisa do mar durante o dia.","convecção","massas de ar quente sobem e o ar do mar vem ocupar o lugar"],["O calor do Sol chega à Terra.","irradiação","ondas eletromagnéticas atravessam o vácuo do espaço"],["Sentir calor perto de uma fogueira, sem encostar.","irradiação","o calor chega como radiação"],["O pão esquenta dentro do forno pela luz da resistência vermelha.","irradiação","radiação térmica"]];
const DEF_CAL={"condução":"Condução: calor passa de partícula a partícula, por contato; principal nos sólidos (metais).","convecção":"Convecção: movimento de líquidos e gases; o quente sobe (menos denso) e o frio desce.","irradiação":"Irradiação: calor por ondas eletromagnéticas; não precisa de meio, atravessa o vácuo."};
tema({id:"c-calor", s:2, nome:"Calor: condução, convecção e irradiação",
aula:`<p><b>Calor</b> é energia térmica em trânsito: passa sempre do corpo <b>mais quente</b> para o <b>mais frio</b>. Há três formas de propagação:</p>
<table><tr><th>Forma</th><th>Como acontece</th><th>Onde</th><th>Exemplos</th></tr>
<tr><td><b>Condução</b></td><td>de partícula em partícula, por <b>contato</b></td><td>principalmente sólidos</td><td>colher esquentando na panela</td></tr>
<tr><td><b>Convecção</b></td><td><b>correntes</b>: o quente sobe (menos denso), o frio desce</td><td>só líquidos e gases</td><td>água fervendo, ar-condicionado no alto, congelador em cima</td></tr>
<tr><td><b>Irradiação</b></td><td>por <b>ondas eletromagnéticas</b>; não precisa de matéria</td><td>até no vácuo</td><td>calor do Sol, fogueira</td></tr></table>
<h4>Condutores e isolantes térmicos</h4><p><b>Condutores</b> deixam o calor passar fácil: metais (por isso a panela é de alumínio). <b>Isolantes</b> dificultam: madeira, plástico, isopor, lã, ar parado (por isso o cabo da panela é de plástico e usamos cobertor).</p>
<p><b>Garrafa térmica</b> evita as três: vácuo entre as paredes (sem condução e convecção) e paredes espelhadas (refletem a irradiação).</p>
<p><i>O cobertor não “esquenta”: ele é isolante e impede que o calor do seu corpo escape.</i></p>`,
gen: rotulo(CAL,Object.keys(DEF_CAL).concat(["sublimação","refração"]),l=>"“"+l[0]+"” Isso ocorre principalmente por:","Há contato direto num sólido? Condução. Há líquido ou gás se movimentando (quente sobe, frio desce)? Convecção. O calor chega à distância, até pelo vácuo? Irradiação.",Object.assign({"sublimação":"Sublimação é mudança de estado (sólido → gás), não propagação de calor.","refração":"Refração é desvio da luz, não propagação de calor."},DEF_CAL))});

/* ---------- 11. VELOCIDADE MÉDIA ---------- */
tema({id:"c-velocidade", s:2, nome:"Movimento e velocidade média",
aula:`<p><b>Velocidade média</b> diz quanto se anda por unidade de tempo:</p><p><b>v = d ÷ t</b> (distância ÷ tempo)</p><p>Daí: <b>d = v × t</b> e <b>t = d ÷ v</b>.</p>
<p><i>Truque do triângulo: escreva <b>d</b> em cima e <b>v</b> e <b>t</b> embaixo. Tape o que você quer: o que sobra mostra a conta (d em cima → divide; v e t lado a lado → multiplica).</i></p>
<h4>Unidades</h4><ul><li>km/h (quilômetros por hora) e m/s (metros por segundo).</li><li><b>km/h → m/s: divida por 3,6</b>. <b>m/s → km/h: multiplique por 3,6</b>. 72 km/h = 20 m/s.</li><li>Cuidado com minutos: 30 min = 0,5 h; 15 min = 0,25 h.</li></ul>
<h4>Exemplo</h4><p>Ônibus percorre 240 km das 8h às 11h. t = 3 h. v = 240 ÷ 3 = <b>80 km/h</b>.</p>
<p><b>Aceleração</b> é a variação da velocidade no tempo: a = Δv ÷ t. Carro vai de 0 a 20 m/s em 4 s → a = 5 m/s².</p>`,
gen(){
  const t=R(4);
  if(t===0){ const v=rint(4,24)*5, h=rint(2,5), d=v*h, ini=rint(6,12); return {q:"Um ônibus saiu às "+ini+"h e chegou às "+(ini+h)+"h, percorrendo "+d+" km. Qual sua velocidade média?",como:"1) Tempo de viagem: "+(ini+h)+"h − "+ini+"h. 2) v = distância ÷ tempo.",c:fmtU(v,"km/h"),w:numW(v,[d/(ini+h),d*h,d/(h+1),d/ini].filter(Number.isInteger),"km/h"),e:"t = "+h+" h. v = "+d+" ÷ "+h+" = "+v+" km/h."}; }
  if(t===1){ const v=rint(3,24)*5, h=pick([0.5,1.5,2,2.5,3,4]), d=v*h; return {q:"Um carro mantém "+v+" km/h durante "+N(h)+" h. Que distância percorre?",como:"d = v × t = "+v+" × "+N(h)+".",c:fmtU(d,"km"),w:numW(d,[v/h,v+h,v*h*2,d/2],"km"),e:v+" × "+N(h)+" = "+N(d)+" km."}; }
  if(t===2){ const ms=pick([5,10,15,20,25,30,40]), kh=ms*3.6, para=R(2); return para?{q:"Quanto é "+N(kh)+" km/h em m/s?",como:"De km/h para m/s: DIVIDA por 3,6.",c:fmtU(ms,"m/s"),w:numW(ms,[kh*3.6,kh/36,kh/10,ms*2],"m/s"),e:N(kh)+" ÷ 3,6 = "+ms+" m/s."}:{q:"Quanto é "+ms+" m/s em km/h?",como:"De m/s para km/h: MULTIPLIQUE por 3,6.",c:fmtU(kh,"km/h"),w:numW(kh,[ms/3.6,ms*36,ms*60,ms*10],"km/h"),e:ms+" × 3,6 = "+N(kh)+" km/h."}; }
  const v=rint(3,15)*10, tt=rint(2,6), d=v*tt; return {q:"Um ciclista quer percorrer "+d+" km a "+v+" km/h. Quanto tempo levará?",como:"t = d ÷ v = "+d+" ÷ "+v+".",c:fmtU(tt,"h"),w:numW(tt,[d*v,v/d*10,tt+1,d/10],"h"),e:d+" ÷ "+v+" = "+tt+" h."};
}});

/* ---------- 12. FORÇAS E LEIS DE NEWTON ---------- */
const NEWT=[["Num ônibus que freia de repente, os passageiros são jogados para a frente.","1ª lei (inércia)","o corpo tende a continuar em movimento"],["Ao puxar rápido a toalha, os pratos ficam na mesa.","1ª lei (inércia)","o corpo parado tende a continuar parado"],["O cinto de segurança protege em freadas bruscas.","1ª lei (inércia)","segura o corpo que tende a seguir em frente"],["Empurrar um carrinho vazio é mais fácil que um cheio.","2ª lei (F = m · a)","mais massa exige mais força para a mesma aceleração"],["Quanto mais forte o chute, mais acelerada sai a bola.","2ª lei (F = m · a)","força maior gera aceleração maior"],["O foguete sobe ao expelir gases para baixo.","3ª lei (ação e reação)","os gases empurram o foguete com força igual e contrária"],["Ao nadar, empurramos a água para trás e vamos para a frente.","3ª lei (ação e reação)","a água empurra o nadador"],["A arma recua ao disparar.","3ª lei (ação e reação)","o projétil vai para um lado e a arma para o outro"],["Ao andar, empurramos o chão para trás.","3ª lei (ação e reação)","o chão nos empurra para a frente"]];
const DEF_NEWT={"1ª lei (inércia)":"Inércia: todo corpo tende a manter seu estado (parado ou em movimento) se nenhuma força agir.","2ª lei (F = m · a)":"2ª lei: força resultante = massa × aceleração.","3ª lei (ação e reação)":"3ª lei: a toda ação há uma reação de mesma intensidade e sentido contrário, em corpos diferentes."};
tema({id:"c-newton", s:2, nome:"Forças, peso e leis de Newton",
aula:`<p><b>Força</b> é uma ação capaz de mudar o movimento ou a forma de um corpo. Unidade: <b>newton (N)</b>.</p>
<h4>As três leis de Newton</h4><ol><li><b>Inércia</b>: um corpo parado tende a continuar parado; em movimento, tende a continuar em linha reta e velocidade constante, se nada o obrigar a mudar. (Freada do ônibus, cinto de segurança.)</li><li><b>F = m · a</b>: a força resultante é a massa vezes a aceleração. Com a mesma força, quem tem mais massa acelera menos.</li><li><b>Ação e reação</b>: se A empurra B, B empurra A com a mesma força, no sentido contrário. (Foguete, nadador, andar.)</li></ol>
<h4>Peso × massa</h4><ul><li><b>Massa</b> (kg): quantidade de matéria. É a mesma na Terra ou na Lua.</li><li><b>Peso</b> (N): força com que o planeta puxa o corpo. <b>P = m · g</b>, com g ≈ <b>10 m/s²</b> na Terra. Uma pessoa de 60 kg pesa 600 N. Na Lua (g ≈ 1,6) pesaria menos, mas teria os mesmos 60 kg.</li></ul>
<h4>Atrito</h4><p>Força que se opõe ao deslizamento entre superfícies. Ajuda a andar e frear; atrapalha ao arrastar móveis.</p>`,
gen: alterna(
  rotulo(NEWT,Object.keys(DEF_NEWT).concat(["lei da gravitação","princípio de Arquimedes"]),l=>"“"+l[0]+"” Esse fato é explicado principalmente pela:","Tendência de continuar como estava (parado ou andando)? Inércia (1ª). Relação entre força, massa e aceleração? 2ª lei. Um empurra e é empurrado de volta? Ação e reação (3ª).",Object.assign({"lei da gravitação":"Gravitação explica a atração entre massas (quedas, órbitas).","princípio de Arquimedes":"Arquimedes explica o empuxo em líquidos."},DEF_NEWT)),
  function(){ const m=rint(2,20)*5, a=rint(1,6), t=R(3);
    if(t===0) return {q:"Qual o peso de um corpo de "+m+" kg na Terra? (g = 10 m/s²)",como:"P = m · g = "+m+" × 10.",c:fmtU(m*10,"N"),w:numW(m*10,[m,m/10,m*100,m+10],"N"),e:m+" × 10 = "+(m*10)+" N."};
    if(t===1) return {q:"Uma força resultante age sobre um carrinho de "+m+" kg, produzindo aceleração de "+a+" m/s². Qual é essa força?",como:"2ª lei: F = m · a = "+m+" × "+a+".",c:fmtU(m*a,"N"),w:numW(m*a,[m/a,m+a,m*10,m*a*10],"N"),e:m+" × "+a+" = "+(m*a)+" N."};
    const F=m*a; return {q:"Uma força de "+F+" N empurra um objeto de "+m+" kg. Qual a aceleração produzida?",como:"De F = m · a, isole a: a = F ÷ m = "+F+" ÷ "+m+".",c:fmtU(a,"m/s²"),w:numW(a,[F*m,m/F*10,F-m,a*10].filter(x=>x>0&&x<1e6),"m/s²"),e:F+" ÷ "+m+" = "+a+" m/s²."}; }
)});

/* ---------- 13. MÁQUINAS SIMPLES ---------- */
const ALAV=[["gangorra","interfixa","o apoio fica no meio"],["tesoura","interfixa","o apoio (parafuso) fica entre a mão e o papel"],["alicate","interfixa","apoio no meio"],["pé de cabra","interfixa","apoio entre a força e a resistência"],["carrinho de mão","inter-resistente","a carga fica entre a roda (apoio) e as mãos"],["quebra-nozes","inter-resistente","a noz fica entre o apoio e a mão"],["abridor de garrafa","inter-resistente","a tampa fica no meio"],["pinça","interpotente","a força é feita no meio"],["vara de pescar","interpotente","uma mão apoia, a outra faz força no meio"],["antebraço levantando peso","interpotente","o músculo faz força entre o cotovelo e a mão"]];
const DEF_ALAV={"interfixa":"Interfixa: o APOIO fica no meio.","inter-resistente":"Inter-resistente: a RESISTÊNCIA (carga) fica no meio.","interpotente":"Interpotente: a FORÇA (potência) fica no meio."};
tema({id:"c-alavancas", s:2, nome:"Máquinas simples e alavancas",
aula:`<p><b>Máquinas simples</b> facilitam o trabalho, diminuindo a força necessária: alavanca, roldana, plano inclinado (rampa), cunha, parafuso, roda e eixo.</p>
<h4>Alavanca</h4><p>Barra que gira em torno de um <b>ponto de apoio</b> (A). Tem a <b>força potente</b> (P, que você faz) e a <b>resistência</b> (R, a carga).</p>
<table><tr><th>Tipo</th><th>O que fica no meio</th><th>Exemplos</th></tr><tr><td><b>Interfixa</b></td><td>o <b>apoio</b></td><td>gangorra, tesoura, alicate</td></tr><tr><td><b>Inter-resistente</b></td><td>a <b>resistência</b></td><td>carrinho de mão, quebra-nozes, abridor</td></tr><tr><td><b>Interpotente</b></td><td>a <b>força</b></td><td>pinça, vara de pescar, antebraço</td></tr></table>
<p><i>Truque: o nome diz o que está “inter” (entre): inter-<b>fixa</b> = apoio fixo no meio; inter-<b>resistente</b>; inter-<b>potente</b>.</i></p>
<h4>Equilíbrio</h4><p><b>Força × braço da força = Resistência × braço da resistência</b> (F · b<sub>F</sub> = R · b<sub>R</sub>). Braço é a distância até o apoio. Quanto <b>maior o braço</b> da força, <b>menor a força</b> necessária. É por isso que maçaneta fica longe da dobradiça.</p>`,
gen: alterna(
  rotulo(ALAV,Object.keys(DEF_ALAV).concat(["roldana fixa","plano inclinado"]),l=>"O(A) "+l[0]+" é uma alavanca do tipo:","Localize os três pontos: apoio (onde gira), força (onde você faz força) e resistência (a carga). Veja qual deles fica no MEIO: apoio → interfixa; resistência → inter-resistente; força → interpotente.",Object.assign({"roldana fixa":"Roldana é uma roda com corda, outra máquina simples.","plano inclinado":"Plano inclinado é uma rampa."},DEF_ALAV)),
  function(){ const R0=rint(2,20)*30, k=pick([2,3,4,5,6]), bR=rint(1,4)*10, bF=bR*k, F=R0/k;
    return {q:"Uma pedra de "+R0+" N está a "+bR+" cm do apoio de uma alavanca. Uma pessoa empurra a outra ponta, a "+bF+" cm do apoio. Que força mínima equilibra a pedra?",como:"Equilíbrio: F × "+bF+" = "+R0+" × "+bR+". Isole F: F = ("+R0+" × "+bR+") ÷ "+bF+".",c:fmtU(F,"N"),w:numW(F,[R0*k,R0,R0-bF,R0/bR],"N"),e:"F = "+R0+" × "+bR+" ÷ "+bF+" = "+N(F)+" N."}; }
)});

/* ---------- 14. PRESSÃO ---------- */
const PRES=[["Uma faca afiada corta melhor que uma cega.","a área de contato é menor, então a pressão é maior"],["Com raquetes de neve, a pessoa não afunda na neve.","a área aumenta e a pressão diminui"],["O prego tem ponta fina.","a área pequena da ponta aumenta a pressão"],["Caminhões pesados têm muitos pneus.","mais pneus = mais área, menos pressão no asfalto"],["Mergulhadores sentem dor no ouvido em grande profundidade.","a pressão da água aumenta com a profundidade"],["A barragem é mais grossa embaixo.","a pressão da água é maior no fundo"],["Tomamos suco de canudinho.","ao sugar, diminui a pressão dentro do canudo e a pressão do ar empurra o suco"],["Salto agulha marca o piso de madeira.","a área minúscula do salto gera pressão enorme"]];
tema({id:"c-pressao", s:2, nome:"Pressão",
aula:`<p><b>Pressão</b> é a força distribuída sobre uma área:</p><p><b>p = F ÷ A</b> (unidade: N/m² = pascal, Pa)</p>
<ul><li><b>Menor área → maior pressão</b>: faca afiada, ponta do prego, salto agulha.</li><li><b>Maior área → menor pressão</b>: raquete de neve, muitos pneus no caminhão, mochila com alça larga.</li></ul>
<h4>Pressão nos líquidos</h4><p>Aumenta com a <b>profundidade</b>: a cada 10 m de água, aumenta cerca de 1 atmosfera. Por isso a barragem é mais grossa embaixo e o ouvido dói ao mergulhar fundo.</p>
<h4>Pressão atmosférica</h4><p>É o peso do ar sobre nós. Ao nível do mar é maior; nas montanhas, menor (há menos ar em cima). Ela explica o canudinho, a ventosa e por que a água ferve a menos de 100 °C em lugares altos.</p>`,
gen: alterna(
  deTabela(PRES,l=>"“"+l[0]+"” A explicação correta é:","Lembre: p = F ÷ A. Com a mesma força, área pequena dá pressão grande; área grande dá pressão pequena. Em líquidos, mais fundo = mais pressão.",l=>"Explicação: "+l[1]+"."),
  function(){ const A=pick([0.5,1,2,4,5]), p=rint(2,20)*100, F=p*A; return {q:"Uma caixa de "+N(F)+" N de peso está apoiada sobre uma área de "+N(A)+" m². Qual a pressão que ela exerce?",como:"p = F ÷ A = "+N(F)+" ÷ "+N(A)+". Resultado em N/m² (pascal).",c:fmtU(p,"Pa"),w:numW(p,[F*A,F,F/A/10,F+A],"Pa"),e:N(F)+" ÷ "+N(A)+" = "+N(p)+" Pa."}; }
)});

/* ---------- 15. DENSIDADE E EMPUXO ---------- */
const DENS=[["óleo",0.9],["madeira (pinho)",0.5],["gelo",0.92],["isopor",0.02],["ferro",7.9],["alumínio",2.7],["ouro",19.3],["chumbo",11.3],["cortiça",0.24],["vidro",2.5],["borracha maciça",1.2],["álcool",0.8]];
tema({id:"c-densidade", s:2, nome:"Densidade, empuxo e flutuação",
aula:`<p><b>Densidade</b> diz quanta massa cabe em um volume: <b>d = m ÷ V</b> (g/cm³). A água tem densidade <b>1 g/cm³</b>.</p>
<ul><li>Densidade <b>menor</b> que a do líquido → <b>flutua</b> (madeira, óleo, gelo, isopor na água).</li><li>Densidade <b>maior</b> → <b>afunda</b> (ferro, pedra, chumbo).</li></ul>
<p><i>Um quilo de algodão e um quilo de ferro pesam igual! Mas o ferro ocupa muito menos espaço: é mais denso.</i></p>
<h4>Empuxo (Princípio de Arquimedes)</h4><p>Todo corpo mergulhado num líquido recebe uma força <b>para cima</b>, o <b>empuxo</b>, igual ao <b>peso do líquido que ele desloca</b>.</p><ul><li>Navio de aço flutua porque é <b>oco</b>: desloca muita água, e o empuxo equilibra o peso.</li><li>Ovo afunda na água doce e flutua na água com muito sal: o sal deixa a água <b>mais densa</b>, aumentando o empuxo.</li><li>Na água, sentimos os objetos “mais leves” por causa do empuxo.</li></ul>`,
gen(){
  if(R(2)){ const [m,d]=pick(DENS), fl=d<1; return {q:"A densidade do(a) "+m+" é cerca de "+N(d)+" g/cm³. Colocado(a) na água (1 g/cm³), ele(a):",como:"Compare com a densidade da água (1 g/cm³): menor → flutua; maior → afunda.",c:fl?"flutua, pois é menos denso que a água":"afunda, pois é mais denso que a água",w:quatro("",["flutua, pois é mais denso que a água","afunda, pois é menos denso que a água","flutua, pois é menos denso que a água","afunda, pois é mais denso que a água","dissolve, pois tem a mesma densidade","fica parado no meio, pois não há empuxo"].filter(x=>x!==(fl?"flutua, pois é menos denso que a água":"afunda, pois é mais denso que a água"))).slice(0,4),e:N(d)+(fl?" < 1 → flutua.":" > 1 → afunda.")}; }
  const V=rint(2,20)*10, d=pick([0.5,0.8,1,2,2.5,4,8]), m=V*d;
  return {q:"Um objeto tem massa de "+N(m)+" g e volume de "+V+" cm³. Qual a sua densidade?",como:"d = m ÷ V = "+N(m)+" ÷ "+V+". O resultado sai em g/cm³. Depois compare com 1 (água) para saber se afunda.",c:fmtU(d,"g/cm³"),w:numW(d,[m*V,V/m,m-V,d*10].filter(x=>x>0&&x<1e5),"g/cm³",false,0.5),e:N(m)+" ÷ "+V+" = "+N(d)+" g/cm³ ("+(d<1?"flutua":d===1?"fica em equilíbrio":"afunda")+" na água)."};
}});

/* ---------- 16. ELETRICIDADE ---------- */
const COND=[["cobre","condutor"],["alumínio","condutor"],["ferro","condutor"],["ouro","condutor"],["água salgada","condutor"],["grafite","condutor"],["corpo humano","condutor"],["borracha","isolante"],["plástico","isolante"],["vidro","isolante"],["madeira seca","isolante"],["isopor","isolante"],["cerâmica (porcelana)","isolante"],["ar seco","isolante"]];
tema({id:"c-eletricidade", s:2, nome:"Eletricidade: circuitos e lei de Ohm",
aula:`<p><b>Corrente elétrica</b> é o movimento ordenado de elétrons por um caminho fechado (<b>circuito</b>). Se o circuito abre (interruptor desligado, fio cortado), a corrente para.</p>
<h4>Grandezas</h4><table><tr><th>Grandeza</th><th>Símbolo</th><th>Unidade</th><th>Ideia</th></tr><tr><td>Tensão (voltagem)</td><td>U</td><td>volt (V)</td><td>o “empurrão” nos elétrons (tomada 127 V ou 220 V; pilha 1,5 V)</td></tr><tr><td>Corrente</td><td>i</td><td>ampère (A)</td><td>quanta carga passa por segundo</td></tr><tr><td>Resistência</td><td>R</td><td>ohm (Ω)</td><td>a dificuldade para a corrente passar</td></tr><tr><td>Potência</td><td>P</td><td>watt (W)</td><td>energia gasta por segundo</td></tr></table>
<h4>Fórmulas</h4><ul><li><b>Lei de Ohm: U = R × i</b></li><li><b>Potência: P = U × i</b></li><li><b>Energia consumida: E = P × t</b> (em kWh: potência em kW × horas). Chuveiro de 5 000 W (5 kW) ligado 2 h → 10 kWh.</li></ul>
<h4>Circuito em série × em paralelo</h4><ul><li><b>Série</b>: um caminho só. Se uma lâmpada queima, <b>todas apagam</b> (pisca-pisca antigo).</li><li><b>Paralelo</b>: vários caminhos. Cada aparelho funciona sozinho e recebe a tensão total. É assim nas <b>casas</b>.</li></ul>
<h4>Condutores × isolantes</h4><p><b>Condutores</b> (metais, água com sais, grafite, corpo humano) deixam a corrente passar. <b>Isolantes</b> (borracha, plástico, vidro, madeira seca) não deixam. Fio: cobre por dentro, plástico por fora.</p>
<p><b>Curto-circuito</b>: a corrente passa por um caminho sem resistência, fica enorme e aquece. Disjuntor e fusível desligam o circuito para proteger.</p>`,
gen(){
  const t=R(5);
  if(t===0){ const l=pick(COND); return {q:"Do ponto de vista elétrico, o(a) "+l[0]+" é um material:",como:"Metais, grafite, água com sais e o corpo humano conduzem. Borracha, plástico, vidro, madeira seca, isopor e cerâmica isolam.",c:l[1],w:["condutor","isolante","supercondutor em casa","gerador de corrente","magnético"].filter(x=>x!==l[1]).slice(0,4),e:l[0]+" é "+l[1]+"."}; }
  if(t===1){ const R0=rint(2,20)*5, i=rint(1,10), U=R0*i; return {q:"Um resistor de "+R0+" Ω é percorrido por uma corrente de "+i+" A. Qual a tensão nele?",como:"Lei de Ohm: U = R × i = "+R0+" × "+i+".",c:fmtU(U,"V"),w:numW(U,[R0/i,R0+i,U*10,U/2].filter(x=>x>0),"V"),e:R0+" × "+i+" = "+U+" V."}; }
  if(t===2){ const U=pick([110,127,220]), i=rint(2,20), P=U*i; return {q:"Um aparelho ligado em "+U+" V é percorrido por "+i+" A. Qual a sua potência?",como:"P = U × i = "+U+" × "+i+".",c:fmtU(P,"W"),w:numW(P,[U/i,U+i,P/10,P*2],"W"),e:U+" × "+i+" = "+P+" W."}; }
  if(t===3){ const P=pick([1000,2000,3000,4000,5000,6000]), h=pick([0.5,1,1.5,2,3]), d=rint(10,30), E=P/1000*h*d; return {q:"Um chuveiro de "+P+" W fica ligado "+N(h)+" h por dia, durante "+d+" dias. Quanto ele consome, em kWh?",como:"1) Passe a potência para kW: "+P+" W ÷ 1 000. 2) E = P (kW) × horas por dia × dias.",c:fmtU(E,"kWh"),w:numW(E,[P*h*d,P/1000*h,E*10,P/1000*d],"kWh"),e:(P/1000)+" kW × "+N(h)+" h × "+d+" = "+N(E)+" kWh."}; }
  const q=pick([["Em uma casa, quando uma lâmpada queima, as outras continuam acesas. Isso ocorre porque o circuito é:","em paralelo"],["Num pisca-pisca antigo, se uma lâmpada queima, todas apagam. As lâmpadas estão ligadas:","em série"]]);
  return {q:q[0],como:"Série = um caminho só: interrompeu em um ponto, tudo para. Paralelo = cada aparelho tem seu caminho: um pode desligar sem afetar os outros.",c:q[1],w:["em série","em paralelo","em curto-circuito","sem fios condutores","com corrente contínua apenas"].filter(x=>x!==q[1]).slice(0,4),e:"Resposta: "+q[1]+"."};
}});

/* ---------- 17. MAGNETISMO ---------- */
const MAG=[["Dois polos norte de ímãs são aproximados. O que acontece?","eles se repelem"],["Um polo norte é aproximado de um polo sul. O que acontece?","eles se atraem"],["Um ímã é quebrado ao meio. Cada pedaço:","vira um novo ímã, com polo norte e polo sul"],["A agulha da bússola aponta para o norte geográfico porque:","a Terra funciona como um grande ímã"],["Qual destes materiais é atraído por um ímã?","ferro"],["O que um fio com corrente elétrica produz ao seu redor?","um campo magnético"],["Um eletroímã é formado por:","um fio enrolado em um prego de ferro, com corrente elétrica"]];
const MAG_W=["eles se repelem","eles se atraem","vira um novo ímã, com polo norte e polo sul","fica só com um polo","perde o magnetismo para sempre","a Terra funciona como um grande ímã","o Sol atrai o ferro da agulha","ferro","alumínio","cobre","um campo magnético","luz visível","um fio enrolado em um prego de ferro, com corrente elétrica","um pedaço de plástico eletrizado"];
tema({id:"c-magnetismo", s:2, nome:"Magnetismo e ímãs",
aula:`<p><b>Ímãs</b> atraem alguns metais, principalmente <b>ferro</b>, níquel e cobalto (alumínio, cobre e ouro <b>não</b> são atraídos).</p>
<ul><li>Todo ímã tem <b>polo norte</b> e <b>polo sul</b>.</li><li><b>Polos iguais se repelem; polos diferentes se atraem.</b></li><li>Quebrando um ímã, cada pedaço vira um ímã completo, com norte e sul. Não existe ímã com um polo só.</li></ul>
<h4>Bússola</h4><p>A <b>Terra é um grande ímã</b>. A agulha da bússola (um pequeno ímã) se alinha com o campo magnético da Terra e aponta para o norte geográfico (onde fica, na verdade, um polo sul magnético).</p>
<h4>Eletromagnetismo</h4><p>Corrente elétrica produz <b>campo magnético</b> (experiência de Oersted). Enrolando fio num prego de ferro e ligando numa pilha, faz-se um <b>eletroímã</b>, que só funciona com corrente (usado em guindastes de ferro-velho, campainhas, motores). E o inverso: ímã se movendo perto de uma bobina gera corrente (geradores, dínamos).</p>`,
gen(){ const [q,c]=pick(MAG); return {q,como:"Lembre: iguais se repelem, diferentes se atraem; ímã quebrado vira dois ímãs; ímã atrai ferro; corrente elétrica cria campo magnético.",c,w:quatro(c,mix(MAG_W)),e:"Resposta: "+c+"."}; }});

/* ---------- 18. LUZ ---------- */
const CORES=["vermelha","verde","azul","amarela"];
const LUZ=[["O lápis parece “quebrado” dentro de um copo com água.","refração","a luz muda de velocidade e de direção ao passar da água para o ar"],["Vemos nossa imagem no espelho.","reflexão","a luz bate e volta"],["O arco-íris aparece após a chuva.","dispersão","a luz branca se separa em cores nas gotas"],["A sombra se forma atrás de um objeto opaco.","propagação retilínea","a luz anda em linha reta e não contorna o objeto"],["Os eclipses acontecem.","propagação retilínea","a luz anda em linha reta e um astro bloqueia o outro"],["A lupa aumenta as letras.","refração","a lente desvia a luz"],["Os óculos corrigem a visão.","refração","as lentes desviam a luz para focar na retina"],["O prisma separa a luz branca em várias cores.","dispersão","cada cor desvia de um jeito"],["A Lua é vista porque é iluminada pelo Sol.","reflexão","a Lua reflete a luz do Sol (não tem luz própria)"]];
tema({id:"c-luz", s:2, nome:"Luz e cor",
aula:`<p>A luz é uma <b>onda eletromagnética</b>: viaja <b>até no vácuo</b>, a cerca de <b>300 000 km/s</b> (a coisa mais rápida que existe). Ela anda em <b>linha reta</b> (por isso há sombras e eclipses).</p>
<h4>Fontes e corpos</h4><ul><li><b>Luminosos</b> (luz própria): Sol, lâmpada acesa, fogo. <b>Iluminados</b> (refletem a luz): Lua, livro, você.</li><li><b>Transparente</b> (vidro limpo), <b>translúcido</b> (vidro fosco, papel vegetal), <b>opaco</b> (madeira, parede).</li></ul>
<h4>Fenômenos</h4><ul><li><b>Reflexão</b>: a luz bate e volta (espelho, Lua).</li><li><b>Refração</b>: a luz muda de meio e <b>desvia</b> (lápis “quebrado” na água, lentes, lupa, óculos).</li><li><b>Dispersão</b>: a luz branca se separa em cores (arco-íris, prisma).</li></ul>
<h4>A cor dos objetos (cai muito!)</h4><p>A luz branca tem todas as cores. Um objeto <b>reflete</b> a cor que vemos e <b>absorve</b> as outras.</p><ul><li>Camiseta vermelha na luz branca: reflete o vermelho → parece vermelha.</li><li>Branco reflete <b>todas</b> as cores; preto <b>absorve todas</b> (por isso esquenta mais no sol).</li><li>Objeto iluminado só por uma cor que ele <b>não reflete</b> → parece <b>preto</b>. Folha verde sob luz vermelha → preta.</li><li>Objeto branco sob luz de uma cor → aparece daquela cor.</li></ul>`,
gen: alterna(
  rotulo(LUZ,["reflexão","refração","dispersão","propagação retilínea","difração do som"],l=>"“"+l[0]+"” Esse fenômeno é explicado pela:","A luz voltou (espelho)? Reflexão. Desviou ao mudar de meio (água, lente)? Refração. Separou-se em cores? Dispersão. Formou sombra/eclipse? Propagação em linha reta.",{"reflexão":"Reflexão: a luz bate e volta.","refração":"Refração: a luz desvia ao mudar de meio.","dispersão":"Dispersão: a luz branca se separa em cores.","propagação retilínea":"Propagação retilínea: a luz anda em linha reta.","difração do som":"Aqui o fenômeno é com a luz, não com o som."}),
  function(){ const obj=pick(CORES.concat(["branca","preta"])), luz=pick(CORES.concat(["branca"]));
    let c; if(obj==="preta") c="preta"; else if(luz==="branca") c=obj; else if(obj==="branca") c=luz; else c=obj===luz?obj:"preta";
    return {q:"Uma camiseta "+obj+" (na luz do dia) é iluminada apenas por luz "+luz+", num quarto escuro. Com que cor ela aparece?",como:"A camiseta só reflete a cor dela ("+(obj==="branca"?"todas":obj==="preta"?"nenhuma":obj)+"). Se a luz que chega for dessa cor, ela aparece; se não, nada é refletido e ela parece preta. Branco reflete qualquer cor; preto absorve tudo.",
      c,w:quatro(c,mix(["vermelha","verde","azul","amarela","branca","preta"])),e:"Ela reflete "+(obj==="branca"?"todas as cores":obj==="preta"?"nenhuma cor":"só o "+obj.replace(/a$/,"o"))+" e recebe luz "+luz+". Resultado: "+c+"."}; }
)});

/* ---------- 19. SOM ---------- */
const SOM=[["O som não se propaga no vácuo.","é uma onda mecânica e precisa de matéria para vibrar"],["Vemos o relâmpago antes de ouvir o trovão.","a luz é muito mais rápida que o som"],["A voz de uma criança é mais aguda que a de um adulto.","tem frequência maior (altura)"],["Aumentar o volume da música.","aumenta a intensidade (amplitude da onda)"],["Reconhecemos a voz de um amigo ao telefone.","cada voz tem um timbre próprio"],["Gritar diante de uma montanha e ouvir de volta.","é o eco, a reflexão do som"],["Encostar o ouvido no trilho para ouvir o trem de longe.","o som é mais rápido nos sólidos"],["O morcego se orienta no escuro.","usa a reflexão do ultrassom (ecolocalização)"]];
tema({id:"c-som", s:2, nome:"Som e ondas",
aula:`<p>O <b>som</b> é uma <b>onda mecânica</b>: é a vibração da matéria passando de partícula em partícula. Por isso <b>precisa de um meio</b> (sólido, líquido ou gás) e <b>não se propaga no vácuo</b> (no espaço não há som).</p>
<h4>Velocidade</h4><p>No ar: cerca de <b>340 m/s</b>. É maior na água (~1 500 m/s) e maior ainda nos sólidos. A luz é quase um milhão de vezes mais rápida: vemos o relâmpago antes de ouvir o trovão.</p><p><b>Distância do raio</b>: d = 340 × tempo (s) entre ver o clarão e ouvir o trovão. 3 s → 1 020 m.</p>
<h4>Qualidades do som</h4><ul><li><b>Altura</b> (frequência, em hertz Hz): <b>agudo</b> (fino, frequência alta) ou <b>grave</b> (grosso, frequência baixa). Não é o volume!</li><li><b>Intensidade</b> (volume): som <b>forte</b> ou <b>fraco</b>; depende da amplitude, medida em decibéis (dB).</li><li><b>Timbre</b>: o que diferencia a mesma nota tocada num violão e num piano, ou a voz de cada pessoa.</li></ul>
<p>Humanos ouvem de ~20 Hz a 20 000 Hz. Abaixo: <b>infrassom</b> (elefantes). Acima: <b>ultrassom</b> (morcegos, golfinhos, exame de ultrassonografia).</p>
<h4>Eco</h4><p>É o som que <b>reflete</b> num obstáculo e volta.</p>`,
gen: alterna(
  deTabela(SOM,l=>"“"+l[0]+"” Isso acontece porque:","Lembre: som é onda mecânica (precisa de meio), anda a 340 m/s no ar (mais rápido em sólidos), altura = agudo/grave (frequência), intensidade = volume, timbre = “assinatura” de cada fonte, eco = reflexão.",l=>"Porque "+l[1]+"."),
  function(){ const t=rint(1,8), d=340*t; return {q:"Durante uma tempestade, uma pessoa vê o relâmpago e ouve o trovão "+t+" segundos depois. A que distância caiu o raio? (som no ar: 340 m/s)",como:"A luz chega praticamente na hora; o atraso é do som. Distância = velocidade do som × tempo = 340 × "+t+".",c:fmtU(d,"m"),w:numW(d,[340/t,340+t,d*10,d/2].filter(Number.isInteger),"m",false,340),e:"340 × "+t+" = "+d+" m."}; }
)});

/* ---------- 20. ECOLOGIA ---------- */
const CADEIAS=[["capim","gafanhoto","sapo","cobra","gavião"],["algas","peixe pequeno","peixe grande","tubarão","—"],["milho","rato","cobra","gavião","—"],["capim","zebra","leão","—","—"],["folhas","lagarta","passarinho","gato-do-mato","—"],["plâncton (algas)","camarão","peixe","garça","—"]];
const NIVEIS=["produtor","consumidor primário","consumidor secundário","consumidor terciário","consumidor quaternário"];
const REL=[["Abelha e flor: a abelha se alimenta do néctar e leva o pólen.","mutualismo","as duas espécies ganham"],["Liquens: alga e fungo vivendo juntos e dependentes.","mutualismo","os dois ganham e dependem um do outro"],["Carrapato no cachorro.","parasitismo","o parasita ganha e o hospedeiro perde"],["Lombriga no intestino humano.","parasitismo","um ganha e o outro é prejudicado"],["Leão caçando zebra.","predação","um mata e come o outro"],["Orquídea crescendo sobre uma árvore, sem prejudicá-la.","inquilinismo","a orquídea ganha apoio; a árvore não ganha nem perde"],["Rêmora acompanha o tubarão e come os restos.","comensalismo","a rêmora ganha restos de comida; o tubarão não é prejudicado"],["Leões e hienas disputando a mesma presa.","competição","disputam o mesmo recurso"],["Formigas trabalhando em um formigueiro.","sociedade","indivíduos da mesma espécie dividem funções"]];
tema({id:"c-ecologia", s:2, nome:"Ecologia: cadeias alimentares e relações",
aula:`<h4>Cadeia alimentar</h4><p>Mostra <b>quem come quem</b>. A seta aponta para quem come: capim → gafanhoto → sapo → cobra.</p>
<ul><li><b>Produtores</b>: fazem o próprio alimento pela <b>fotossíntese</b> (plantas, algas). Sempre o 1º elo.</li><li><b>Consumidores</b>: 1º (primário) come o produtor (herbívoro); 2º come o 1º; 3º come o 2º...</li><li><b>Decompositores</b>: fungos e bactérias. Decompõem restos e devolvem nutrientes ao solo. Atuam em todos os níveis.</li></ul>
<p><i>Truque: conte as setas a partir do produtor. Gafanhoto está a 1 passo → consumidor primário. Sapo a 2 → secundário.</i></p>
<h4>Energia</h4><p>A energia vem do <b>Sol</b> e <b>diminui</b> a cada nível (cerca de 90% se perde em calor, movimento, respiração). Por isso as cadeias têm poucos elos e há mais capim que gaviões. <b>Teia alimentar</b> = várias cadeias interligadas.</p>
<h4>Relações ecológicas</h4><table><tr><th>Relação</th><th>Quem ganha/perde</th><th>Exemplo</th></tr><tr><td>Mutualismo</td><td>os dois ganham</td><td>abelha e flor, liquens</td></tr><tr><td>Comensalismo</td><td>um ganha, outro neutro (restos de comida)</td><td>rêmora e tubarão</td></tr><tr><td>Inquilinismo</td><td>um ganha abrigo/apoio, outro neutro</td><td>orquídea na árvore</td></tr><tr><td>Parasitismo</td><td>um ganha, outro perde (sem matar logo)</td><td>carrapato, lombriga</td></tr><tr><td>Predação</td><td>um mata e come o outro</td><td>leão e zebra</td></tr><tr><td>Competição</td><td>os dois perdem (disputa)</td><td>leões e hienas</td></tr><tr><td>Sociedade</td><td>mesma espécie, divisão de tarefas</td><td>formigas, abelhas</td></tr></table>`,
gen: alterna(
  function(){ const cad=pick(CADEIAS).filter(x=>x!=="—"), i=rint(0,cad.length-1), c=NIVEIS[i];
    return {q:"Na cadeia alimentar "+cad.join(" → ")+", o(a) "+cad[i]+" é:",como:"O primeiro elo (que faz fotossíntese) é o produtor. Depois conte quantas setas separam o ser do produtor: 1 = consumidor primário; 2 = secundário; 3 = terciário.",c,w:quatro(c,NIVEIS.concat(["decompositor"])),e:cad[i]+" está "+(i?"a "+i+" passo(s) do produtor":"no início, faz fotossíntese")+": "+c+".",def:{decompositor:"Decompositores são fungos e bactérias, que não aparecem nesta cadeia."}}; },
  rotulo(REL,["mutualismo","parasitismo","predação","inquilinismo","comensalismo","competição","sociedade"],l=>"“"+l[0]+"” Essa relação ecológica é:","Pergunte: os dois ganham? (mutualismo) Um ganha e o outro perde sem morrer na hora? (parasitismo) Um mata e come? (predação) Um ganha e o outro nem percebe? (comensalismo, se for comida; inquilinismo, se for abrigo/apoio) Disputa? (competição)",null),
  function(){ return {q:"Em uma cadeia alimentar, a energia que passa de um nível para o seguinte:",como:"Lembre: cada ser vivo usa parte da energia para viver (respirar, andar) e perde parte em calor. Só uma pequena parte passa adiante.",c:"diminui, pois parte se perde como calor e nas atividades do ser vivo",w:["aumenta, pois os animais maiores têm mais energia","permanece igual, pois a energia é reciclada","é produzida pelos decompositores","volta inteira para o produtor"],e:"A energia diminui a cada nível (cerca de 10% passa adiante)."}; }
)});

/* ---------- 21. CÉLULAS ---------- */
const ORG=[["membrana plasmática","controla a entrada e a saída de substâncias"],["núcleo","guarda o material genético (DNA) e comanda a célula"],["mitocôndria","faz a respiração celular e libera energia"],["cloroplasto","faz a fotossíntese (só em células vegetais)"],["ribossomo","produz proteínas"],["parede celular","dá rigidez e proteção (célula vegetal)"],["citoplasma","região entre a membrana e o núcleo, onde ficam as organelas"],["vacúolo","armazena água e substâncias (grande na célula vegetal)"],["lisossomo","faz a digestão dentro da célula"]];
tema({id:"c-celulas", s:2, nome:"Células e organelas",
aula:`<p>A <b>célula</b> é a menor unidade viva. Todo ser vivo é formado por células: uma só (bactérias, amebas: <b>unicelulares</b>) ou muitas (plantas, animais: <b>pluricelulares</b>).</p>
<h4>Partes básicas</h4><ul><li><b>Membrana plasmática</b>: “porteiro”, controla o que entra e sai.</li><li><b>Citoplasma</b>: o interior, com as organelas.</li><li><b>Núcleo</b>: guarda o <b>DNA</b> e comanda a célula.</li></ul>
<h4>Organelas</h4><table><tr><th>Organela</th><th>Função</th></tr><tr><td>Mitocôndria</td><td>respiração celular: libera <b>energia</b> (“usina”)</td></tr><tr><td>Cloroplasto</td><td><b>fotossíntese</b> (só vegetais e algas)</td></tr><tr><td>Ribossomo</td><td>produz <b>proteínas</b></td></tr><tr><td>Lisossomo</td><td>digestão dentro da célula</td></tr><tr><td>Vacúolo</td><td>armazena água e substâncias</td></tr><tr><td>Parede celular</td><td>rigidez (vegetais, fungos, bactérias)</td></tr></table>
<h4>Animal × vegetal</h4><p>A <b>vegetal</b> tem a mais: <b>parede celular</b>, <b>cloroplastos</b> e um <b>vacúolo grande</b>.</p>
<h4>Procarionte × eucarionte</h4><p><b>Procarionte</b>: sem núcleo organizado, DNA solto (bactérias). <b>Eucarionte</b>: com núcleo (animais, plantas, fungos, protozoários).</p>
<h4>Níveis de organização</h4><p>célula → tecido → órgão → sistema → organismo.</p>`,
gen: alterna(
  deTabela(ORG,l=>"Qual a função do(a) "+l[0]+"?","Associe a organela à “tarefa”: energia = mitocôndria; fotossíntese = cloroplasto; proteínas = ribossomo; controle e DNA = núcleo; entrada e saída = membrana.",l=>l[0]+": "+l[1]+".",1),
  function(){ const l=pick(ORG); return {q:"Qual estrutura da célula "+l[1]+"?",como:"Leia a função e lembre da tabela da aula.",c:l[0],w:outras(ORG,l,x=>x[0]).slice(0,4),e:l[0]+": "+l[1]+"."}; },
  function(){ const q=pick([["Qual destas estruturas existe na célula vegetal, mas NÃO na animal?",pick(["cloroplasto","parede celular"]),["mitocôndria","núcleo","membrana plasmática","ribossomo","citoplasma"]],["As bactérias são células procariontes porque:","não têm núcleo organizado; o DNA fica solto no citoplasma",["têm núcleo e cloroplastos","são formadas por muitas células","não têm DNA","têm parede de madeira"]],["Qual a sequência correta dos níveis de organização?","célula → tecido → órgão → sistema → organismo",["tecido → célula → órgão → sistema → organismo","órgão → célula → tecido → sistema → organismo","célula → órgão → tecido → organismo → sistema","sistema → órgão → tecido → célula → organismo"]]]);
    return {q:q[0],como:"Revise a aula: a vegetal tem parede, cloroplasto e vacúolo grande; procarionte = sem núcleo; níveis vão do menor (célula) ao maior (organismo).",c:q[1],w:sample(q[2],4),e:"Resposta: "+q[1]+"."}; }
)});

/* ---------- 22. CORPO HUMANO ---------- */
const CORPO=[["coração","bombeia o sangue para o corpo","circulatório"],["pulmões","fazem as trocas gasosas: entra O₂ no sangue, sai CO₂","respiratório"],["rins","filtram o sangue e formam a urina","urinário (excretor)"],["estômago","digere proteínas com suco gástrico ácido","digestório"],["intestino delgado","absorve os nutrientes dos alimentos","digestório"],["intestino grosso","absorve água e forma as fezes","digestório"],["fígado","produz a bile, que ajuda a digerir gorduras","digestório"],["cérebro","comanda o corpo, pensamento e memória","nervoso"],["medula espinhal","conduz mensagens entre o cérebro e o corpo e controla reflexos","nervoso"],["traqueia","leva o ar até os brônquios","respiratório"],["diafragma","músculo que ajuda a encher e esvaziar os pulmões","respiratório"],["bexiga","armazena a urina","urinário (excretor)"],["pâncreas","produz insulina e suco pancreático","digestório (e endócrino)"],["glóbulos vermelhos (hemácias)","transportam oxigênio no sangue","circulatório"],["glóbulos brancos (leucócitos)","defendem o corpo contra micróbios","imunológico"],["plaquetas","ajudam na coagulação do sangue","circulatório"],["ossos","sustentam o corpo e protegem órgãos","esquelético"],["boca","começa a digestão: mastiga e a saliva digere o amido","digestório"]];
tema({id:"c-corpo", s:2, nome:"Corpo humano: sistemas e órgãos",
aula:`<table><tr><th>Sistema</th><th>Função</th><th>Órgãos principais</th></tr>
<tr><td><b>Digestório</b></td><td>quebra o alimento e absorve nutrientes</td><td>boca (saliva) → faringe → esôfago → estômago (suco gástrico) → intestino delgado (<b>absorção</b>) → intestino grosso (água, fezes). Glândulas: fígado (bile), pâncreas.</td></tr>
<tr><td><b>Respiratório</b></td><td>troca gasosa</td><td>nariz → faringe → laringe → traqueia → brônquios → pulmões (<b>alvéolos</b>, onde o O₂ entra no sangue e o CO₂ sai). Diafragma.</td></tr>
<tr><td><b>Circulatório</b></td><td>transporta O₂, nutrientes e resíduos</td><td>coração (4 cavidades), artérias (saem do coração), veias (voltam), capilares. Sangue: hemácias (O₂), leucócitos (defesa), plaquetas (coagulação).</td></tr>
<tr><td><b>Urinário</b></td><td>filtra o sangue e elimina resíduos</td><td>rins → ureteres → bexiga → uretra.</td></tr>
<tr><td><b>Nervoso</b></td><td>comanda e coordena</td><td>cérebro, cerebelo (equilíbrio), medula espinhal (reflexos), nervos.</td></tr>
<tr><td><b>Esquelético e muscular</b></td><td>sustentação e movimento</td><td>206 ossos; músculos.</td></tr>
<tr><td><b>Endócrino</b></td><td>hormônios</td><td>pâncreas (insulina), tireoide, hipófise.</td></tr>
<tr><td><b>Imunológico</b></td><td>defesa</td><td>glóbulos brancos, anticorpos.</td></tr></table>
<p><b>Pegadinhas:</b> a absorção de nutrientes é no intestino <b>delgado</b> (não no estômago). O fígado <b>produz</b> a bile (a vesícula só guarda). Artéria <b>sai</b> do coração, veia <b>chega</b>.</p>`,
gen: alterna(
  deTabela(CORPO,l=>"Qual a principal função do(a) "+l[0]+"?","Pense no sistema do órgão (digestório, respiratório, circulatório, urinário, nervoso) e na tarefa dele. Reveja a tabela da aula.",l=>l[0]+": "+l[1]+" (sistema "+l[2]+")."),
  function(){ const l=pick(CORPO); return {q:"Qual órgão ou estrutura "+l[1]+"?",como:"Leia a função e lembre de qual sistema ela faz parte; depois escolha o órgão.",c:l[0],w:outras(CORPO,l,x=>x[0]).slice(0,4),e:l[0]+": "+l[1]+"."}; },
  function(){ const l=pick(CORPO); return {q:"O(A) "+l[0]+" faz parte do sistema:",como:"Lembre da função: "+l[1]+". Em qual sistema isso se encaixa?",c:l[2],w:quatro(l[2],mix([...new Set(CORPO.map(x=>x[2]))])),e:l[0]+" → sistema "+l[2]+"."}; }
)});

/* ---------- 23. SAÚDE E DOENÇAS ---------- */
const DOEN=[["dengue","vírus","picada do mosquito Aedes aegypti","eliminar água parada"],["gripe","vírus","gotículas no ar (tosse, espirro)","vacina, lavar as mãos"],["covid-19","vírus","gotículas e aerossóis","vacina, máscara e higiene"],["sarampo","vírus","gotículas no ar","vacina"],["tuberculose","bactéria","gotículas no ar","vacina BCG e tratamento"],["tétano","bactéria","ferimento com objeto contaminado","vacina antitetânica"],["cólera","bactéria","água e alimentos contaminados","água tratada e saneamento"],["malária","protozoário","picada do mosquito Anopheles","combate ao mosquito"],["doença de Chagas","protozoário","fezes do barbeiro","melhorar moradias e combater o barbeiro"],["giardíase","protozoário","água e alimentos contaminados","água tratada, lavar alimentos"],["ascaridíase (lombriga)","verme","ovos em água e alimentos contaminados","lavar mãos e alimentos, saneamento"],["teníase (solitária)","verme","carne de porco ou boi mal cozida","cozinhar bem a carne"],["esquistossomose (barriga-d’água)","verme","larvas na água de lagoas contaminadas","não nadar em água contaminada, saneamento"],["amarelão (ancilostomose)","verme","larvas que entram pela pele do pé","usar calçados"]];
tema({id:"c-saude", s:2, nome:"Saúde: doenças, prevenção e vacinas",
aula:`<h4>Quem causa as doenças</h4><ul><li><b>Vírus</b>: dengue, gripe, covid-19, sarampo, catapora, aids. Antibiótico <b>não</b> funciona contra vírus.</li><li><b>Bactérias</b>: tuberculose, tétano, cólera, pneumonia bacteriana. Tratadas com <b>antibióticos</b>.</li><li><b>Protozoários</b>: malária, doença de Chagas, giardíase, amebíase.</li><li><b>Vermes</b> (verminoses): lombriga, solitária (teníase), esquistossomose, amarelão.</li></ul>
<h4>Como se pegam e como prevenir</h4><table><tr><th>Transmissão</th><th>Doenças</th><th>Prevenção</th></tr><tr><td>Mosquito</td><td>dengue, zika, chikungunya (Aedes); malária (Anopheles)</td><td>acabar com água parada, repelente, telas</td></tr><tr><td>Ar (tosse, espirro)</td><td>gripe, covid, tuberculose, sarampo</td><td>vacina, máscara, ambiente ventilado</td></tr><tr><td>Água/alimento contaminado</td><td>cólera, giardíase, lombriga, hepatite A</td><td>água tratada, lavar mãos e alimentos, saneamento</td></tr><tr><td>Carne mal cozida</td><td>teníase</td><td>cozinhar bem</td></tr><tr><td>Pele (pé descalço)</td><td>amarelão</td><td>usar calçado</td></tr><tr><td>Barbeiro</td><td>Chagas</td><td>casas de alvenaria, combater o inseto</td></tr></table>
<h4>Vacina × soro</h4><p><b>Vacina</b>: prevenção. Contém o micróbio morto, enfraquecido ou partes dele; o corpo aprende a produzir <b>anticorpos</b> e cria memória. <b>Soro</b>: tratamento de emergência. Já traz os anticorpos prontos (picada de cobra, por exemplo).</p>
<p><b>Saneamento básico</b> (água tratada, esgoto, coleta de lixo) é a melhor arma contra verminoses e muitas doenças.</p>`,
gen(){
  const d=pick(DOEN), t=R(3);
  if(t===0) return {q:"A "+d[0]+" é causada por um(a):",como:"Lembre dos grupos: vírus (dengue, gripe, covid, sarampo), bactéria (tuberculose, tétano, cólera), protozoário (malária, Chagas, giardíase), verme (lombriga, solitária, esquistossomose, amarelão).",c:d[1],w:quatro(d[1],["vírus","bactéria","protozoário","verme","fungo"]),e:d[0]+": "+d[1]+"."};
  if(t===1) return {q:"Como é transmitida a "+d[0]+"?",como:"Pense no causador e no modo de contágio: mosquito, ar, água/alimento, carne mal cozida, pele, inseto barbeiro.",c:d[2],w:outras(DOEN,d,x=>x[2]).slice(0,4),e:d[0]+": "+d[2]+". Prevenção: "+d[3]+"."};
  if(R(2)) return {q:"Uma medida eficaz de prevenção da "+d[0]+" é:",como:"A prevenção sempre “corta” o caminho de transmissão. Como a "+d[0]+" é transmitida? Escolha a medida que impede esse caminho.",c:d[3],w:outras(DOEN,d,x=>x[3]).slice(0,4),e:d[0]+" ("+d[2]+"): "+d[3]+"."};
  const q=pick([["A vacina protege porque:","estimula o corpo a produzir anticorpos e criar memória contra o micróbio"],["Uma pessoa picada por cobra venenosa deve receber:","soro, que já contém anticorpos prontos"],["Antibióticos servem para tratar doenças causadas por:","bactérias"]]);
  return {q:q[0],como:"Vacina = prevenção (o corpo aprende a se defender). Soro = anticorpos prontos para emergência. Antibiótico só mata bactérias.",c:q[1],w:quatro(q[1],mix(["estimula o corpo a produzir anticorpos e criar memória contra o micróbio","soro, que já contém anticorpos prontos","bactérias","vírus","vacina, que age na hora","mata todos os vírus do sangue na hora","um antibiótico","vermes"])),e:"Resposta: "+q[1]+"."};
}});

/* ---------- 24. GENÉTICA E EVOLUÇÃO ---------- */
const EVO=[["Bactérias resistentes a antibióticos se multiplicam após o uso errado do remédio.","Darwin (seleção natural)","as que já eram resistentes sobreviveram e se reproduziram"],["A girafa esticou o pescoço para alcançar folhas e passou isso aos filhotes.","Lamarck (uso e desuso)","ideia de herança de características adquiridas, hoje descartada"],["Mariposas escuras ficaram mais comuns em cidades com fuligem nas árvores.","Darwin (seleção natural)","as escuras eram menos vistas pelos predadores"],["Um ferreiro forte terá filhos fortes por causa do seu treino.","Lamarck (uso e desuso)","características adquiridas não passam pelos genes"],["Entre os coelhos, os mais rápidos escapam das raposas e deixam mais filhotes.","Darwin (seleção natural)","o ambiente seleciona as variações favoráveis"]];
tema({id:"c-evolucao", s:2, nome:"Genética e evolução",
aula:`<h4>Genética</h4><ul><li>O <b>DNA</b> fica no núcleo das células e carrega as informações hereditárias. Trechos do DNA com uma informação são os <b>genes</b>. O DNA fica organizado em <b>cromossomos</b> (humanos têm 46: 23 da mãe e 23 do pai).</li><li>Cada característica tem dois genes (um de cada pai). O gene <b>dominante</b> (letra maiúscula, A) se manifesta mesmo com um só; o <b>recessivo</b> (a) só aparece em dose dupla (aa).</li><li>Cruzamento Aa × Aa: AA, Aa, aA, aa → <b>3/4</b> mostram o dominante e <b>1/4</b> o recessivo.</li></ul>
<h4>Evolução</h4><p>As espécies <b>mudam ao longo de muitas gerações</b>. Evidências: fósseis, semelhanças entre embriões e entre o DNA.</p>
<ul><li><b>Lamarck</b> (ideia antiga, descartada): “uso e desuso” e herança do que foi adquirido. A girafa esticaria o pescoço e passaria isso aos filhos. <b>Errado</b>: o que se adquire na vida (músculos de academia) não passa pelos genes.</li><li><b>Darwin</b> (aceita): <b>seleção natural</b>. 1) Indivíduos de uma espécie já são <b>diferentes</b> entre si (variação). 2) O ambiente favorece alguns. 3) Os mais adaptados <b>sobrevivem e se reproduzem mais</b>, passando suas características. Girafas que <b>já nasciam</b> com pescoço maior comiam mais e deixavam mais filhotes.</li></ul>
<p>Hoje se sabe que a variação vem de <b>mutações</b> no DNA e da mistura de genes na reprodução sexuada.</p>`,
gen: alterna(
  rotulo(EVO,["Darwin (seleção natural)","Lamarck (uso e desuso)","criacionismo","geração espontânea","fixismo (as espécies nunca mudam)"],l=>"“"+l[0]+"” Essa explicação corresponde à ideia de:","Se a explicação diz que o ser MUDOU por esforço/uso durante a vida e passou isso aos filhos → Lamarck. Se diz que as variações JÁ existiam e o ambiente escolheu quem sobrevive e se reproduz → Darwin.",{"Darwin (seleção natural)":"Darwin: variações já existem; o ambiente seleciona.","Lamarck (uso e desuso)":"Lamarck: uso e desuso e herança do adquirido (descartada).","criacionismo":"Criacionismo é crença religiosa, não explica por mecanismo natural.","geração espontânea":"Geração espontânea dizia que a vida surge da matéria sem vida (refutada).","fixismo (as espécies nunca mudam)":"Fixismo diz que as espécies não mudam; os fatos mostram mudança."}),
  function(){ const q=pick([["Do cruzamento de dois pais Aa (heterozigotos), qual a proporção de filhos aa (com a característica recessiva)?","1/4"],["Do cruzamento Aa × Aa, que fração dos filhos mostra a característica dominante?","3/4"],["Do cruzamento AA × aa, que fração dos filhos é Aa?","1 (todos)"],["Do cruzamento Aa × aa, qual a chance de um filho ser aa?","1/2"]]);
    return {q:q[0],como:"Faça o quadro: escreva os genes de um pai na linha e do outro na coluna e combine (são 4 casas). Conte quantas casas atendem ao pedido e divida por 4. Lembre: basta um A para mostrar o dominante.",c:q[1],w:quatro(q[1],["1/4","3/4","1/2","1 (todos)","0 (nenhum)"]),e:"Pelo quadro de cruzamento: "+q[1]+"."}; },
  function(){ const q=pick([["Onde fica o material genético (DNA) nas células humanas?","no núcleo"],["Quantos cromossomos há em uma célula humana comum?","46 (23 pares)"],["A principal fonte de novas variações nos seres vivos são as:","mutações no DNA"]]);
    return {q:q[0],como:"Revise a parte de genética da aula.",c:q[1],w:quatro(q[1],mix(["no núcleo","na membrana","46 (23 pares)","23","mutações no DNA","vacinas","no sangue apenas","100","exercícios físicos"])),e:"Resposta: "+q[1]+"."}; }
)});

/* ---------- 25. ASTRONOMIA ---------- */
const PLAN=["Mercúrio","Vênus","Terra","Marte","Júpiter","Saturno","Urano","Netuno"];
const ASTRO=[["O dia e a noite acontecem por causa da:","rotação da Terra em torno do próprio eixo (cerca de 24 h)"],["O ano (365 dias) corresponde ao tempo da:","translação da Terra em volta do Sol"],["As estações do ano acontecem por causa da:","inclinação do eixo da Terra durante a translação"],["As fases da Lua acontecem porque:","vemos partes diferentes da face iluminada da Lua enquanto ela gira em volta da Terra"],["O eclipse solar acontece quando:","a Lua fica entre o Sol e a Terra"],["O eclipse lunar acontece quando:","a Terra fica entre o Sol e a Lua"],["O Sol é:","uma estrela, com luz própria"],["A Lua é:","o satélite natural da Terra, sem luz própria"],["O planeta mais próximo do Sol é:","Mercúrio"],["O maior planeta do Sistema Solar é:","Júpiter"],["O planeta conhecido pelos seus grandes anéis é:","Saturno"],["As marés são causadas principalmente pela:","atração gravitacional da Lua"]];
tema({id:"c-astronomia", s:2, nome:"Astronomia: Terra, Lua e Sistema Solar",
aula:`<h4>Movimentos da Terra</h4><ul><li><b>Rotação</b>: gira em torno de si em ~24 h → <b>dia e noite</b>.</li><li><b>Translação</b>: volta em torno do Sol em ~365 dias → <b>ano</b>. Com a <b>inclinação do eixo</b> (~23,5°), causa as <b>estações</b>. (Não é a distância ao Sol! Quando é verão no Brasil, é inverno na Europa.)</li></ul>
<h4>A Lua</h4><ul><li>Satélite natural, <b>sem luz própria</b>: reflete a luz do Sol.</li><li>Fases (~29,5 dias): <b>nova → crescente → cheia → minguante</b>. Metade dela está sempre iluminada; conforme gira em torno da Terra, vemos mais ou menos dessa metade.</li><li>Atração da Lua causa as <b>marés</b>.</li></ul>
<h4>Eclipses</h4><ul><li><b>Solar</b>: a <b>Lua</b> fica no meio (Sol – Lua – Terra), na lua nova.</li><li><b>Lunar</b>: a <b>Terra</b> fica no meio (Sol – Terra – Lua) e faz sombra na Lua, na lua cheia.</li></ul>
<h4>Sistema Solar</h4><p>O <b>Sol</b> é uma <b>estrela</b>. Oito planetas, em ordem: <b>Mercúrio, Vênus, Terra, Marte</b> (rochosos), <b>Júpiter, Saturno, Urano, Netuno</b> (gasosos/gigantes).</p><p><i>Frase para decorar: “<b>M</b>inha <b>V</b>ó <b>T</b>em <b>M</b>uitas <b>J</b>oias, <b>S</b>ó <b>U</b>sa <b>N</b>o pescoço.”</i></p><p>Júpiter é o maior; Saturno tem os anéis mais visíveis; Vênus é o mais quente; Plutão hoje é planeta-anão.</p>`,
gen: alterna(
  function(){ const [q,c]=pick(ASTRO); const pool=ASTRO.map(x=>x[1]).filter(x=>x!==c); return {q,como:"Rotação = dia/noite; translação + inclinação = ano e estações; fases = parte iluminada que vemos; eclipse solar = Lua no meio; lunar = Terra no meio.",c,w:quatro(c,mix(pool)),e:"Resposta: "+c+"."}; },
  function(){ const i=rint(0,7), ordem=["1º","2º","3º","4º","5º","6º","7º","8º"]; return {q:"Contando a partir do Sol, qual é o "+ordem[i]+" planeta do Sistema Solar?",como:"Use a frase: “Minha Vó Tem Muitas Joias, Só Usa No pescoço” → Mercúrio, Vênus, Terra, Marte, Júpiter, Saturno, Urano, Netuno.",c:PLAN[i],w:quatro(PLAN[i],mix(PLAN.concat(["Plutão"]))),e:"Ordem: "+PLAN.join(", ")+". O "+ordem[i]+" é "+PLAN[i]+"."}; }
)});

})();
